INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 162,'Мир и покой тебе, путник. Зачем ты ищешь меня сегодня?' FROM `quest_template` b WHERE b.`id`=162 AND BINARY b.`requestitemstext`=BINARY 'Peace and tranquility be upon you, stranger.  Why have you sought me out this day?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 198,'Да? Чего тебе? А, припасы от гоблинов. Странно, что их доставляет $R: обычно они посылают своих. Впрочем, неважно... Ты ведь их не трогаешь? Хорошо, хорошо... Не хотелось бы, чтобы с нашими минами что-нибудь случилось, о нет.' FROM `quest_template` b WHERE b.`id`=198 AND BINARY b.`requestitemstext`=BINARY 'Yes? What do you want? Oh, supplies from the goblins. Strange seeing a $R delivering them, usually they send their own. No matter... you didn\'t touch them did you? Good good... we wouldn\'t want anything to happen to our mines, oh no.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 203,'Надеюсь, охота прошла удачно, $N. Без твоей помощи мы против него долго не продержимся.' FROM `quest_template` b WHERE b.`id`=203 AND BINARY b.`requestitemstext`=BINARY 'I hope you\'ve been successful in your hunting, $N. We won\'t last long against him without your help.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 204,'Отличная работа, $N. Благодаря этим лекарствам больше наших бойцов выживут и останутся в строю. А экстракты помогут нам создать собственные лекарства.' FROM `quest_template` b WHERE b.`id`=204 AND BINARY b.`offerrewardtext`=BINARY 'Well done, $N. These remedies will keep more of us alive and in fighting shape. And the extracts will help us create our own remedies.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 204,'Я жду лекарства и экстракт, $N.' FROM `quest_template` b WHERE b.`id`=204 AND BINARY b.`requestitemstext`=BINARY 'I\'m waiting on those remedies and that extract, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 206,'Благословляю тебя. С силой Май\'Зота может сравниться лишь его злоба.' FROM `quest_template` b WHERE b.`id`=206 AND BINARY b.`requestitemstext`=BINARY 'I give you my blessing. Mai\'Zoth\'s strength is matched only by his evil.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 207,'Спасибо, $N. Я изучу эти легенды, чтобы выяснить, есть ли связь между троллями и злом, завладевшим полковником Курценом.' FROM `quest_template` b WHERE b.`id`=207 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N. I will study these legends to see if there is some link between the trolls and the evil that has possessed Colonel Kurzen.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 207,'$N! Легенды троллей у тебя? Я должен узнать их тайны!' FROM `quest_template` b WHERE b.`id`=207 AND BINARY b.`requestitemstext`=BINARY '$N! Do you have the troll legends? I must know their secrets!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 209,'Крепкие твари, а? Ну что, есть успехи? Прости за нетерпение, но они мне уже поперёк горла! Ну?' FROM `quest_template` b WHERE b.`id`=209 AND BINARY b.`requestitemstext`=BINARY 'Tough buggers, aren\'t they? Well, have you had any luck? Sorry to seem impatient, but this has been a huge thorn in my side! Well?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 338,'Главы уже собраны, $N?' FROM `quest_template` b WHERE b.`id`=338 AND BINARY b.`requestitemstext`=BINARY 'Have you assembled the chapters yet, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 339,'Наконец-то! Глава I собрана!' FROM `quest_template` b WHERE b.`id`=339 AND BINARY b.`offerrewardtext`=BINARY 'At last! Chapter I is complete!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 339,'Неужели удалось разыскать страницы 1, 4, 6 и 8? Только этих четырёх нам и не хватает, чтобы собрать главу I.' FROM `quest_template` b WHERE b.`id`=339 AND BINARY b.`requestitemstext`=BINARY 'I don\'t suppose you were able to track down pages 1, 4, 6 and 8?  Those four are all we need to piece Chapter I back together.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 340,'Наконец-то глава II собрана! Отличная работа!' FROM `quest_template` b WHERE b.`id`=340 AND BINARY b.`offerrewardtext`=BINARY 'Chapter II is finally complete! Well done!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 340,'Чтобы закончить главу II, нам ещё нужны страницы 10, 11, 14 и 16, $N.' FROM `quest_template` b WHERE b.`id`=340 AND BINARY b.`requestitemstext`=BINARY 'We still need pages 10, 11, 14 and 16 to complete Chapter II, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 341,'Фух! Отличная работа, $N. Теперь глава III снова собрана целиком!' FROM `quest_template` b WHERE b.`id`=341 AND BINARY b.`offerrewardtext`=BINARY 'Phew! Good work, $N. Chapter III is now back together in one piece!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 341,'Есть успехи с поиском страниц 18, 20, 21 или 24? Только они нам и нужны, чтобы собрать главу III.' FROM `quest_template` b WHERE b.`id`=341 AND BINARY b.`requestitemstext`=BINARY 'Any luck with pages 18, 20, 21 or 24?  Those are the only ones we need to piece together Chapter III.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 342,'Великолепно! Теперь глава IV готова!' FROM `quest_template` b WHERE b.`id`=342 AND BINARY b.`offerrewardtext`=BINARY 'Superb! We now have Chapter IV ready to go!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 342,'Чтобы закончить главу IV, нужны всего три страницы, $N. Страницы 25, 26 или 27 уже у тебя?' FROM `quest_template` b WHERE b.`id`=342 AND BINARY b.`requestitemstext`=BINARY 'We just need three pages to finish off Chapter IV, $N.  Do you have pages 25, 26 or 27 yet?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 349,'Знахарь Унбагва знает, что нравится Мокку Дикарю. Да, да!$b$bЯ говорю с духами и заставляю его прийти, да.$b$bНо другие гориллы тоже любят разговоры с духами. Ты защищаешь Знахаря Унбагву, а я привожу его к тебе.$b$bНо сперва Знахарю Унбагве кое-что нужно. Принеси Клык гориллы, и я начну говорить с духами!' FROM `quest_template` b WHERE b.`id`=349 AND BINARY b.`requestitemstext`=BINARY 'Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!$b$bMe speak with spirits and make he come, I do.$b$bBut other Gorilla-beast like spirit talkin\' too.  You protect Witch Doctor Unbagwa and I make he come to you.$b$bWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 500,'Очень хорошо, $N Наверное, ради всех этих костяшек тебе пришлось перебить целую ораву огров.$B$BТеперь они должны от нас отстать. Хотя бы на время.' FROM `quest_template` b WHERE b.`id`=500 AND BINARY b.`offerrewardtext`=BINARY 'Very good, $N You must have hacked through a whole mess of ogres to get all these knucklebones.$B$BThat should keep them out of our hair. At least, for a while.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 500,'$N, ты всё ещё охотишься на огров? Где костяшки, которые я просил собрать?' FROM `quest_template` b WHERE b.`id`=500 AND BINARY b.`requestitemstext`=BINARY '$N, are you still hunting ogres? Do you have the knucklebones I had you gather?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 510,'$N, тебя что-то тревожит. Хочешь мне что-то сказать?' FROM `quest_template` b WHERE b.`id`=510 AND BINARY b.`requestitemstext`=BINARY '$N, you look anxious. Is there something you wish to tell me?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 511,'Да, $N? У тебя ко мне дело?' FROM `quest_template` b WHERE b.`id`=511 AND BINARY b.`requestitemstext`=BINARY 'Yes, $N? Do you have some business with me?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 523,'Спасибо, $N. Мне спокойнее за свою голову, когда я знаю, что злодей лишился своей.' FROM `quest_template` b WHERE b.`id`=523 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N. My head rests a little easier, knowing that villain lost his.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 523,'Неужели Барон Вардус думает, что Южнобережье позволит ему безнаказанно натравливать на нас своих головорезов? Я хочу его голову!' FROM `quest_template` b WHERE b.`id`=523 AND BINARY b.`requestitemstext`=BINARY 'Baron Vardus cannot think Southshore will allow him to send his thugs against us with impunity. I want his head!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 540,'Хотел бы я тоже обыскать руины, но боюсь, мои кости не выдержат подъёма в горы. А как продвигаются твои поиски знаний, $N?' FROM `quest_template` b WHERE b.`id`=540 AND BINARY b.`requestitemstext`=BINARY 'I wish I could search the ruins too, but I fear these bones wouldn\'t hold me during my climb up the mountains. However, how does your hunt for knowledge progress, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 554,'Мудрое решение. Вряд ли найдётся другой учёный, способный перевести этот свиток. А если в нём окажется что-нибудь интересное, не беспокойся. Я за тобой пошлю.' FROM `quest_template` b WHERE b.`id`=554 AND BINARY b.`offerrewardtext`=BINARY 'A wise decision. I don\'t believe there is a scholar other than myself with the skills to translate this scroll. And if its contents prove interesting, fear not. I will send for you.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 554,'Опять отвлекают?$B$BА, этот пергамент покрыт очень сложным, тонко сплетённым заклинанием. Конечно, я могу его распутать, но на это нужно время. А моё время очень дорого...$B$BМожет, я просто куплю его у тебя?' FROM `quest_template` b WHERE b.`id`=554 AND BINARY b.`requestitemstext`=BINARY 'More interruptions?$B$BAh, this parchment is covered with a very intricate, finely woven spell. I can untangle it, of course, but it\'s going to take time. And time is very valuable to me...$B$BPerhaps I will just purchase it from you?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 559,'Головы для меня у тебя, $N?' FROM `quest_template` b WHERE b.`id`=559 AND BINARY b.`requestitemstext`=BINARY 'Did you get those heads for me, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 560,'Приветствую, гражданин. Ты пришёл помочь нам защитить Южнобережье?' FROM `quest_template` b WHERE b.`id`=560 AND BINARY b.`requestitemstext`=BINARY 'Greetings, citizen. Have you come to lend your arm to upholding the safety of Southshore?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 563,'Что это? А-а... значит, мой прилежный ученик всерьёз занялся нагами в Южнобережье. Спасибо, что приносишь мне это. Я непременно учту твоё усердие при пересмотре назначений в следующем месяце.' FROM `quest_template` b WHERE b.`id`=563 AND BINARY b.`offerrewardtext`=BINARY 'What\'s this? Ah... so my attentive pupil has applied himself to the problem of the naga in Southshore. Thank you for bringing this to me, I will certainly take it into account when I review personnel assignments in the next month.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 563,'Приветствую, гражданин. Чем может помочь городская стража Штормграда?' FROM `quest_template` b WHERE b.`id`=563 AND BINARY b.`requestitemstext`=BINARY 'Greetings, citizen. May the Stormwind city guard be of assistance?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 574,'Сержант Йохва говорит, что вы умелы и храбры, $C. Вам есть о чем сообщить?' FROM `quest_template` b WHERE b.`id`=574 AND BINARY b.`requestitemstext`=BINARY 'Sergeant Yohwa tells me you are skilled and brave, $C. Do you have something to report?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 587,'Отлично, $n! И как раз перед отплытием! Даже не знаю, как тебя отблагодарить, дружище.' FROM `quest_template` b WHERE b.`id`=587 AND BINARY b.`offerrewardtext`=BINARY 'Good show, $n!  And just before I need to ship out too!  Can\'t thank you enough, old friend.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 587,'Ну что, дружище, удалось найти товары?' FROM `quest_template` b WHERE b.`id`=587 AND BINARY b.`requestitemstext`=BINARY 'Any luck finding the goods, matey?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 594,'Ты здесь, чтобы меня освободить?' FROM `quest_template` b WHERE b.`id`=594 AND BINARY b.`offerrewardtext`=BINARY 'Have you come to free me?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 601,'Есть успехи, $N?' FROM `quest_template` b WHERE b.`id`=601 AND BINARY b.`requestitemstext`=BINARY 'Have you had any luck, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 602,'Если не возражаешь, я сейчас очень занят.' FROM `quest_template` b WHERE b.`id`=602 AND BINARY b.`requestitemstext`=BINARY 'If you wouldn\'t mind, I am rather busy right now.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 605,'Ага! Это отлично подойдёт, $N. Да, просто замечательно!$B$BВот твоя доля, и... было приятно иметь с тобой дело.' FROM `quest_template` b WHERE b.`id`=605 AND BINARY b.`offerrewardtext`=BINARY 'Aha!  These will do nicely, $N.  Yes, quite nicely!$B$BHere is your cut, and...it was a pleasure doing business with you.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 605,'Ну что, осколки у тебя? Я поделюсь с тобой прибылью, и неплохо!' FROM `quest_template` b WHERE b.`id`=605 AND BINARY b.`requestitemstext`=BINARY 'Do you have those shards yet?  I\'ll give you a decent cut from the profits!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 608,'Ах, какой замечательный день для Пиратов Черноводья! Троекратное ура тебе, $n!' FROM `quest_template` b WHERE b.`id`=608 AND BINARY b.`offerrewardtext`=BINARY 'Ah, what a great day for the Blackwater Raiders!  Three cheers to you, $n!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 609,'$N, удалось найти тех трёх псов? А забрать их ценности?' FROM `quest_template` b WHERE b.`id`=609 AND BINARY b.`requestitemstext`=BINARY '$N, did you find those three dogs? Did you collect their valuables?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 611,'Камень приливов уже у тебя, $N? Я освободил для него место и купил красивую подставку.' FROM `quest_template` b WHERE b.`id`=611 AND BINARY b.`requestitemstext`=BINARY 'Have you retrieved the Stone of the Tides for me, $N? I\'ve already cleared out a space and purchased a fine stand for it.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 613,'Вот оно! Огромное спасибо, $N. Ты мне очень помог!$b$bДержи — это заслуженная награда!' FROM `quest_template` b WHERE b.`id`=613 AND BINARY b.`offerrewardtext`=BINARY 'You found it! Thanks a million, $N. You\'ve been a big help to me!$b$bHere you go - you earned this!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 614,'Йо-хо-хо, $N! Удалось найти Горлаша? Это был мой любимый сундук, а в потайном отделении хранились мои величайшие сокровища!' FROM `quest_template` b WHERE b.`id`=614 AND BINARY b.`requestitemstext`=BINARY 'Ahoy, $N! Did you find Gorlash? That chest was my favorite, and it has a hidden compartment that held my greatest treasures!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 617,'Если у тебя ко мне дел нет, проходи мимо, $N.' FROM `quest_template` b WHERE b.`id`=617 AND BINARY b.`requestitemstext`=BINARY 'If ya got no business with me, then move along, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 621,'А, отлично! Вот твоя плата.$B$BИ ещё кое-что сверху... за молчание.' FROM `quest_template` b WHERE b.`id`=621 AND BINARY b.`offerrewardtext`=BINARY 'Ah, very good!  Here is your pay.$B$BAnd here is a little something extra... for your discretion.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 621,'Образцы Смеси Занзила у тебя??' FROM `quest_template` b WHERE b.`id`=621 AND BINARY b.`requestitemstext`=BINARY 'Do you have the samples of Zanzil\'s Mixture??' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 622,'Здравствуй, $N. Удалось добраться до Пиратской Бухты? Гоблин Кразек починил мой котёл??' FROM `quest_template` b WHERE b.`id`=622 AND BINARY b.`requestitemstext`=BINARY 'Hello, $N. Did you make it to Booty Bay? Did the goblin Krazek fix my pot??' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 623,'А?' FROM `quest_template` b WHERE b.`id`=623 AND BINARY b.`requestitemstext`=BINARY 'Yeah?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 625,'Вы находите затхлый свиток.' FROM `quest_template` b WHERE b.`id`=625 AND BINARY b.`offerrewardtext`=BINARY 'You find a musty scroll.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 630,'$N, благодаря тебе я избежал великого бесчестья. Будь это в моей власти, я предложил бы тебе место в моём племени. Но пока я могу лишь вручить тебе этот дар в знак признания твоей отваги и благородства.' FROM `quest_template` b WHERE b.`id`=630 AND BINARY b.`offerrewardtext`=BINARY '$N, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 630,'Благодарю предков за то, что кто-то пришёл мне на помощь. У тебя есть ключ, который меня освободит?' FROM `quest_template` b WHERE b.`id`=630 AND BINARY b.`requestitemstext`=BINARY 'I thank my ancestors someone has come to aid me. Do you have the key that will free me?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 653,'Леди рассказала мне о твоём приходе, $C. Добро пожаловать в мою обитель: ты, как и я, служишь высшей цели.' FROM `quest_template` b WHERE b.`id`=653 AND BINARY b.`offerrewardtext`=BINARY 'The Lady told me of your coming, $C. You are welcome in my abode for you, like I, serve a higher cause.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 656,'Сейчас кристаллы Мизраэль необычно тихие.' FROM `quest_template` b WHERE b.`id`=656 AND BINARY b.`requestitemstext`=BINARY 'The Shards of Myzrael are now strangely quiet.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 659,'Старайся не шуметь, путник.$B$BОркам не нравится, когда за ними шпионят, а эта ферма не так проста, как кажется.' FROM `quest_template` b WHERE b.`id`=659 AND BINARY b.`offerrewardtext`=BINARY 'Try and stay as quiet as possible, traveler.$B$BOrcs don\'t take too well to being spied on, and there is more to this farm than meets the eye.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 681,'$N, с каждым часом нам всё труднее удерживать Стромгард. Поторопись, иначе наш город непременно падёт.' FROM `quest_template` b WHERE b.`id`=681 AND BINARY b.`requestitemstext`=BINARY '$N, with each passing hour our hold on Stromgarde grows more tenuous. You must make haste or our city will surely fall.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 682,'Спасибо, $N. Мы сообщим семьям павших солдат, что те погибли в бою.$b$bНелегко будет передать эти мрачные вести, но это лучше неизвестности о судьбе близкого человека.' FROM `quest_template` b WHERE b.`id`=682 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N. We will inform the families of these fallen soldiers that they were killed in battle.$b$bIt will be grim news to bear, but it is better than the uncertainty of a missing loved one.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 684,'Приветствую, $C. Есть что доложить?' FROM `quest_template` b WHERE b.`id`=684 AND BINARY b.`requestitemstext`=BINARY 'Greetings, $C. You have a report to make?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 685,'Здравствуй. Есть что доложить?' FROM `quest_template` b WHERE b.`id`=685 AND BINARY b.`requestitemstext`=BINARY 'Hello. Do you have a report to submit?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 687,'Привет. Привет, привет, привет, привет, привет, ПРИВЕТ!$B$BПрости... постой, нет, я не прошу прощения! Не груби!$B$BО нет... что за безумные речи.$B$BНо... иногда лишь в безумии я нахожу утешение.' FROM `quest_template` b WHERE b.`id`=687 AND BINARY b.`offerrewardtext`=BINARY 'Hello. Hello, hello hello hello hello HELLO!$B$BI\'m sorry - wait, no I\'m not! Don\'t be rude!$B$BOh no...that was crazy talk.$B$BBut...sometimes being crazy is my only solace.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 692,'Осколки нашлись?!?! Если хочешь снова заточить её, понадобится Свиток Мизраэль. Пока ещё не поздно!' FROM `quest_template` b WHERE b.`id`=692 AND BINARY b.`requestitemstext`=BINARY 'Did you find those fragments?!?! You\'ll need the Scroll of Myzrael if you want to trap her again, before it\'s too late!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 694,'Ты меня удивляешь, $N. Снова отличная работа.$B$BДай мне немного времени наложить нужные чары на самоцвет, и всё будет готово.' FROM `quest_template` b WHERE b.`id`=694 AND BINARY b.`offerrewardtext`=BINARY 'You amaze me, $N. Well done again.$B$BGive me a moment to cast the proper spell to enchant the gem, an\' you\'ll be ready.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 695,'Хорошо, хорошо.$b$bЕсли больше ничто не задерживает, может, начнём?' FROM `quest_template` b WHERE b.`id`=695 AND BINARY b.`offerrewardtext`=BINARY 'Good, good.$b$bIf there are no other delays, how about we get started?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 696,'У тебя все получится, и я уверен, Малин будет более чем доволен тобой.' FROM `quest_template` b WHERE b.`id`=696 AND BINARY b.`requestitemstext`=BINARY 'You do this, an\' I\'m sure Malin\'ll be more than pleased with you.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 697,'Да? Твоё лицо кажется знакомым. Прошу прощения, мы встречались? Дел столько, что всего не упомнишь.' FROM `quest_template` b WHERE b.`id`=697 AND BINARY b.`requestitemstext`=BINARY 'Yes? You look vaguely familiar. I do apologize, but have we met? I get so busy I lose track.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 703,'А, сейчас же займусь этими крылышками. Я уже почти чувствую их вкус!$b$bА вот рецепт, если захочешь приготовить их самостоятельно!' FROM `quest_template` b WHERE b.`id`=703 AND BINARY b.`offerrewardtext`=BINARY 'Ah, I\'ll get started on those wings right away. I can almost taste them already!$b$bAnd here\'s the recipe in case you want to make them yourself!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 703,'Здравствуй, $N. Мои крылья у тебя?' FROM `quest_template` b WHERE b.`id`=703 AND BINARY b.`requestitemstext`=BINARY 'Hello, $N. Did you bring me my wings?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 705,'Они отлично подойдут! Осталось растолочь их в порошок... потом смешать немного этого и немного того.$b$bБерегитесь, падальщики! Приготовьтесь к ослепительной вспышке!' FROM `quest_template` b WHERE b.`id`=705 AND BINARY b.`offerrewardtext`=BINARY 'These will work great! I just need to smash them into powder...then mix them with a little of this and a little of that.$b$bWatch out, scavengers! Prepare to be flashed!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 706,'Ах да, это отлично подойдёт. Теперь твоё оружие сможет наносить обжигающие удары!' FROM `quest_template` b WHERE b.`id`=706 AND BINARY b.`offerrewardtext`=BINARY 'Ah yes, this will do excellently. This will enable your weapons to strike with searing heat!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 706,'Как идёт охота, $C?' FROM `quest_template` b WHERE b.`id`=706 AND BINARY b.`requestitemstext`=BINARY 'How goes the hunt, $C?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 709,'О, удача на нашей стороне! Спасибо! Может, мы ещё спасёмся!' FROM `quest_template` b WHERE b.`id`=709 AND BINARY b.`offerrewardtext`=BINARY 'Oh, fortune is with us! Thank you! We may yet be saved!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 709,'Табличка найдена? Она должна хранить тайны! Тайны, которые нас спасут!' FROM `quest_template` b WHERE b.`id`=709 AND BINARY b.`requestitemstext`=BINARY 'Did you find the tablet? It must hold secrets! Secrets to save us!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 710,'Это место идеально подходит для... Не подержишь вот это минутку? Да, вот так, вдоль вектора нормали. Так, о чём я... Точно. Идеально подходит для испытания моего последнего изобретения. Сырьё, простор... чего ещё желать умному и просвещённому мастеру своего дела?' FROM `quest_template` b WHERE b.`id`=710 AND BINARY b.`requestitemstext`=BINARY 'This area\'s perfect for-- Could you hold these in place for a moment? Yes, just like that, along the vector normal. Now, what was I... Right. Perfect for testing my latest project. The raw materials, the open space... what more could an intelligent and enlightened practitioner of the arts ask for?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 711,'$N, просто невероятно! Я думал, чтобы принести всё это, понадобится полдюжины тауренов.' FROM `quest_template` b WHERE b.`id`=711 AND BINARY b.`offerrewardtext`=BINARY '$N, simply amazing! I would have thought it\'d take half a dozen tauren to bring all these to me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 711,'Я очень доволен, $N. Мои заклинания подействовали на мелкие кусочки именно так, как я предсказывал. Если опыт пройдёт настолько успешно, как я рассчитываю, элементали под моим контролем затмят всё, что призывали до сих пор.' FROM `quest_template` b WHERE b.`id`=711 AND BINARY b.`requestitemstext`=BINARY 'I\'m most pleased, $N. My spells affected the smaller pieces just as I predicted. If this experiment is as successful as I foresee, then the elementals I\'ll be able to control will put anything summoned prior to this to shame.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 713,'Удалось найти нужное мне масло? Оно бы очень пригодилось.' FROM `quest_template` b WHERE b.`id`=713 AND BINARY b.`requestitemstext`=BINARY 'Have you found the oil I need? It would be so helpful if you were able to find some.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 714,'Да, да, да. Минутку.$b$b' FROM `quest_template` b WHERE b.`id`=714 AND BINARY b.`requestitemstext`=BINARY 'Yes, yes, yes. Just a moment.$b$b' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 715,'Он почти закончил. А как дела у тебя?' FROM `quest_template` b WHERE b.`id`=715 AND BINARY b.`requestitemstext`=BINARY 'He\'s getting closer to finishing. How are things going on your end?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 716,'Держи, $N. Примерь.' FROM `quest_template` b WHERE b.`id`=716 AND BINARY b.`offerrewardtext`=BINARY 'Here you go, $N. Try these on.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 718,'Огромное спасибо, $N. Пока тебя не было, я... э-э... наглотался песка. Он...$B$BВпрочем, хватит об этом. Сегодня вечером пойдём поедим. Попируем по-королевски!' FROM `quest_template` b WHERE b.`id`=718 AND BINARY b.`offerrewardtext`=BINARY 'Thanks so much, $N. While you were gone, I... er... swallowed a mouthful of sand. It...$B$BWell, enough of that, we\'ll go out and get some food tonight. Eat like kings!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 727,'О. Приветствую, брат.$B$BИ хвала тем, кто обитает внизу.' FROM `quest_template` b WHERE b.`id`=727 AND BINARY b.`offerrewardtext`=BINARY 'Oh. Greetings, brother.$B$BAnd praise to the dwellers beneath.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 727,'Здравствуй. Добро пожаловать в мою лавку, только ничего не трогай без спроса.$B$BЗнания могут быть смертельно опасны.' FROM `quest_template` b WHERE b.`id`=727 AND BINARY b.`requestitemstext`=BINARY 'Hello. Welcome to my shop, but watch what you touch.$B$BKnowledge can be deadly.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 733,'Ну, я обошёлся тем, что было, но... этого мало. Удалось найти ещё припасы?' FROM `quest_template` b WHERE b.`id`=733 AND BINARY b.`requestitemstext`=BINARY 'Well, I\'ve made do with what I could, but... it\'s not much. Have you found any more supplies?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 734,'Зубец #5, значит? Да, хорошего ждать не приходится.' FROM `quest_template` b WHERE b.`id`=734 AND BINARY b.`offerrewardtext`=BINARY 'Cog #5, huh? Yeah, this isn\'t going to be good.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 735,'А ты находчивый, $C. Если тебе и впрямь поручено открыть новое отделение нашего ордена, думаю, ты хорошо с ним справишься.' FROM `quest_template` b WHERE b.`id`=735 AND BINARY b.`offerrewardtext`=BINARY 'You are resourceful, $C. If it truly is your charge to begin a new chapter of our order, then I believe you will run it well.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 735,'Реликвии, о которых я просил, у тебя?' FROM `quest_template` b WHERE b.`id`=735 AND BINARY b.`requestitemstext`=BINARY 'Do you have the relics for which I asked?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 737,'Вот оно! О, появилась надежда!$B$BБлагодаря тебе мы ещё можем спастись, $N. Тебе бы памятник поставить! Святилище воздвигнуть! Пусть твоё имя славят до тех пор, пока у твоих внуков не появятся внуки!$B$BЕсли только... ОНИ не освободятся и не поднимутся на поверхность. Если это случится, о детях можешь забыть.$B$BЕсли ОНИ освободятся, все мы пойдём на корм червям.' FROM `quest_template` b WHERE b.`id`=737 AND BINARY b.`offerrewardtext`=BINARY 'You got it! Oh, hope glimmers!$B$BYour efforts may yet save us, $N. A monument they should make of you! A shrine they should build! May your name be praised until your grandchildren have grandchildren!$B$BUnless...THEY are freed and rise to the surface.  If that happens then you can forget about children.$B$BIf THEY are freed, then we\'re all worm food.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 737,'Ого! Долго же тебя не было. Сборник у тебя?' FROM `quest_template` b WHERE b.`id`=737 AND BINARY b.`requestitemstext`=BINARY 'Ho! You were gone a long time. Did you get the digest?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 778,'Не совсем тот исход, на который я рассчитывал. Не вернёшь мои кандалы?' FROM `quest_template` b WHERE b.`id`=778 AND BINARY b.`requestitemstext`=BINARY 'Not quite the outcome I was expecting. Could you get my shackles back?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 779,'Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.' FROM `quest_template` b WHERE b.`id`=779 AND BINARY b.`offerrewardtext`=BINARY 'As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 779,'Перед вами печать Земли. В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.' FROM `quest_template` b WHERE b.`id`=779 AND BINARY b.`requestitemstext`=BINARY 'The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 939,'Что такое, $C? Тебя что-то тревожит.' FROM `quest_template` b WHERE b.`id`=939 AND BINARY b.`requestitemstext`=BINARY 'What is it, $C? You look concerned.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 969,'А-а, да... Сейчас я сделаю тебе оберег. Только подожди!' FROM `quest_template` b WHERE b.`id`=969 AND BINARY b.`offerrewardtext`=BINARY 'Ahh, yes... I will make da charm for ya now. Just you wait!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 969,'Принеси осколки, тогда расскажу больше!' FROM `quest_template` b WHERE b.`id`=969 AND BINARY b.`requestitemstext`=BINARY 'Bring back da shards, and I be tellin\' you more!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 975,'Вот, держи, $N. Помни, его нужно носить с собой. Возвращайся в Зимние Ключи и посмотри, что там удастся найти.' FROM `quest_template` b WHERE b.`id`=975 AND BINARY b.`offerrewardtext`=BINARY 'Here it is, $N. Remember, ya have ta carry it with you. Why don\'t ya head back to Winterspring, an\' see what ya be findin\' there?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 977,'Не терпится показать друзьям! Погоди минутку, я только прикреплю вот это...$b$bИдеально!' FROM `quest_template` b WHERE b.`id`=977 AND BINARY b.`offerrewardtext`=BINARY 'I can\'t wait to show my friends! Now, just wait a moment while I attach these...$b$bPerfect!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 977,'Я почти закончил прикреплять мех, $N. Прошу, поскорее возвращайся с рогами!' FROM `quest_template` b WHERE b.`id`=977 AND BINARY b.`requestitemstext`=BINARY 'I\'ve just about finished attaching the fur, $N. Please, hurry back with those horns!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1106,'Тебя прислал Пшикс? Это всё меняет! Конечно, я помогу. Пшикс и его брат — одни из немногих, кто не желает мне смерти!$b$bЗначит, Пшиксу нужны поршни? Такие прочные, чтобы выдержать все задуманные им нагрузки? Зная Пшикса, могу сказать: его новая машина — настоящий вулкан на колёсах!' FROM `quest_template` b WHERE b.`id`=1106 AND BINARY b.`offerrewardtext`=BINARY 'Fizzle sent you? Well that changes things! Of course I\'ll help you. Fizzle and his brother are two of the few people who don\'t want me dead!$b$bSo Fizzle wants to make pistons, eh? Pistons strong enough to take whatever stresses he has planned, and if I know Fizzle, then this new car of his is a volcano on wheels!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 1120,'Привет! У тебя что-то для меня?' FROM `quest_template` b WHERE b.`id`=1120 AND BINARY b.`requestitemstext`=BINARY 'Hi! You have something for me?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 1121,'На что смотришь?' FROM `quest_template` b WHERE b.`id`=1121 AND BINARY b.`requestitemstext`=BINARY 'What are you looking at?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 1122,'Здравствуй, $N. Ну как тебе тот портер? Крепкая штука, правда?' FROM `quest_template` b WHERE b.`id`=1122 AND BINARY b.`requestitemstext`=BINARY 'Hello $N. How\'d that stout work out? It\'s strong stuff, isn\'t it?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1190,'На свитке торопливым почерком набросаны записи и чертежи для обработки какого-то сырья.' FROM `quest_template` b WHERE b.`id`=1190 AND BINARY b.`offerrewardtext`=BINARY 'Scribbled in a hasty, hurried hand, a scroll of notes and designs for the refinement of some raw material.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1191,'Вперёд!' FROM `quest_template` b WHERE b.`id`=1191 AND BINARY b.`offerrewardtext`=BINARY 'Let\'s go!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1192,'Отлично! Команда немедленно займётся деталями для следующей гонки.' FROM `quest_template` b WHERE b.`id`=1192 AND BINARY b.`offerrewardtext`=BINARY 'Excellent! I\'ll get the crew to work right away on the parts we\'ll need for the next race.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1194,'Индарилий? Интересно... Если он и вправду выдерживает такой жар, это объясняет, почему гномы в последнее время добились столь впечатляющих результатов.$B$BЭтот образец тоже будет бесценен для меня. Я смогу провести кое-какие испытания, но, чтобы извлечь из этого настоящую пользу, понадобится больше материала.' FROM `quest_template` b WHERE b.`id`=1194 AND BINARY b.`offerrewardtext`=BINARY 'Indurium? Interesting... If it is capable of resisting heat to the degree that you say, it would explain the performance increase the gnomes have displayed of late.$B$BThis sample you\'ve brought to me will be invaluable, also. I will be able to perform some tests on this, but I\'ll need more for this to actually be of any use to us.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1518,'Отлично!$B$BТотем, который я сделаю для тебя, — больше, чем просто символ твоего положения, $C. У него есть и другие свойства. Например, он может служить средоточием заклинаний. Эти заклинания связаны с землёй, и чем мудрее ты становишься, тем больше её сил тебе открывается.$B$BНаставники поймут, когда ты будешь готов к новым знаниям.$B$BА пока возьми этот тотем земли и свиток, который научит тебя первой способности.' FROM `quest_template` b WHERE b.`id`=1518 AND BINARY b.`offerrewardtext`=BINARY 'Excellent!$B$BThe totem I will craft for you is more than a symbol of your status among $C--it has abilities beyond that. One use of the totem is as a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth\'s abilities will be made accessible to you.$B$BThe trainers will know when you are ready for greater knowledge.$B$BBut for now, take this earth totem, and a scroll to teach you your first ability.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 1518,'Я хочу первым поприветствовать тебя на первом из четырёх путей, которые навсегда определят твою судьбу.$B$BЕсли у тебя есть камень, полученный от земли, я отдам тебе обещанный ею тотем.$B$BЕсли нет, уходи и возвращайся, когда найдёшь свой путь.' FROM `quest_template` b WHERE b.`id`=1518 AND BINARY b.`requestitemstext`=BINARY 'I wish to be the first to welcome you fully to the first of four paths that will forever lead you in your destiny.$B$BIf you have the stone the earth gave to you, I will give you the totem it promised.$B$BIf not, then be gone with you until you have found your way.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1707,'Отлично! Чем больше бурдюков с водой мы вернём, тем дальше будем от беды! Приноси ещё, и за каждые пять бурдюков я непременно тебя награжу.' FROM `quest_template` b WHERE b.`id`=1707 AND BINARY b.`offerrewardtext`=BINARY 'Excellent - the more water pouches we are able to reclaim, the further away from disaster we\'ll all be!  Keep \'em coming, and I will be sure to reward you for every five water pouches you bring me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 1878,'Отлично! Чем больше бурдюков с водой мы вернём, тем дальше будем от беды! Приноси ещё, и за каждые пять бурдюков я непременно тебя награжу.' FROM `quest_template` b WHERE b.`id`=1878 AND BINARY b.`offerrewardtext`=BINARY 'Excellent - the more water pouches we are able to reclaim, the further away from disaster we\'ll all be! Keep \'em coming, and I will be sure to reward you for every five water pouches you bring me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 2605,'О, чудесно! Давай сюда — я это выпью!' FROM `quest_template` b WHERE b.`id`=2605 AND BINARY b.`offerrewardtext`=BINARY 'Oh, wonderful! Give it here -- let me drink it!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2605,'Пожалуйста, скажи, что удалось найти сборники росы?' FROM `quest_template` b WHERE b.`id`=2605 AND BINARY b.`requestitemstext`=BINARY 'Please, tell me you found the dew collectors?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 2641,'То, что надо, $N!$B$BВыглядит так аппетитно, что я бы... Ха-ха, обманул!' FROM `quest_template` b WHERE b.`id`=2641 AND BINARY b.`offerrewardtext`=BINARY 'That\'s the stuff, $N!$B$BIt looks so good, I might just...  Haha, gotcha!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2641,'Фиалковый траган растёт только под водой в том озере. Надеюсь, ты умеешь надолго задерживать дыхание!' FROM `quest_template` b WHERE b.`id`=2641 AND BINARY b.`requestitemstext`=BINARY 'Under the waters of that lake -- it\'s the only place where the Violet Tragan can be found.  Hope you\'re good at holding your breath!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 2661,'Фиалковый порошок, значит? Давай попробуем — хуже от него точно не станет!' FROM `quest_template` b WHERE b.`id`=2661 AND BINARY b.`offerrewardtext`=BINARY 'Violet Powder, eh? Let\'s give it a try -- it sure couldn\'t make it any worse, that\'s for sure!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2661,'О, $N, наконец-то ты здесь. Что у тебя?' FROM `quest_template` b WHERE b.`id`=2661 AND BINARY b.`requestitemstext`=BINARY 'Oh, $N, you\'re finally back.  What have you brought?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 2748,'Очень хорошо, $N. Я отправлю это яйцо в Дарнас и надеюсь, что оно скоро вылупится!$B$BПрошу, прими это в знак моей благодарности.' FROM `quest_template` b WHERE b.`id`=2748 AND BINARY b.`offerrewardtext`=BINARY 'Very good, $N. I will be sending this egg to Darnassus where I hope it will soon hatch!$B$BPlease accept this as a symbol of my gratitude.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 2749,'Значит, у тебя обыкновенное яйцо, $N? Дай его мне... Остаётся надеяться на лучшее.$B$BУ меня немногое есть, но всё же прими эту награду. Если вновь окажешься в Фераласе, помни: я всегда готов принять найденные тобой яйца.' FROM `quest_template` b WHERE b.`id`=2749 AND BINARY b.`offerrewardtext`=BINARY 'So, you have found an ordinary egg, $N? Please give it to me... And we can only hope for the best.$B$BI don\'t have much, but please accept this reward. If you ever find yourself in Feralas again, know that I am always here to take the eggs you find there.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2749,'Из обычных яиц гиппогрифов птенцы вылупляются примерно в половине случаев. Мы заботимся о них как можем, и, если повезёт, они вылупятся.' FROM `quest_template` b WHERE b.`id`=2749 AND BINARY b.`requestitemstext`=BINARY 'Ordinary hippogryph eggs hatch about half the time. We do our best to nurture them and with a little luck, they will hatch.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2750,'Эти яйца уже не спасти — из них никто не вылупится.' FROM `quest_template` b WHERE b.`id`=2750 AND BINARY b.`requestitemstext`=BINARY 'These are the eggs that cannot be saved -- they will never hatch.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 2771,'Превосходно! По-моему, вполне честный обмен. Смотри и учись, $N!' FROM `quest_template` b WHERE b.`id`=2771 AND BINARY b.`offerrewardtext`=BINARY 'Excellent! A fair tradeoff, if I do say so myself. Watch and learn, $N!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2771,'Изготовление предметов завершено, $N?' FROM `quest_template` b WHERE b.`id`=2771 AND BINARY b.`requestitemstext`=BINARY 'Have you completed the crafting of the items, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 2772,'Весь мир будет у твоих ног, $N! Пусть все пытаются подсечь тебя — теперь тебя не сбить с ног!' FROM `quest_template` b WHERE b.`id`=2772 AND BINARY b.`offerrewardtext`=BINARY 'The world will be at your feet, $N! Let them all come at your legs, for you are now unsweepable!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2772,'Изготовление предметов завершено, $N?' FROM `quest_template` b WHERE b.`id`=2772 AND BINARY b.`requestitemstext`=BINARY 'Have you completed the crafting of the items, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2773,'Изготовление предметов завершено, $N?' FROM `quest_template` b WHERE b.`id`=2773 AND BINARY b.`requestitemstext`=BINARY 'Have you completed the crafting of the items, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2875,'У тебя какой-то ошалелый вид. Наши юридические документы читаешь?' FROM `quest_template` b WHERE b.`id`=2875 AND BINARY b.`requestitemstext`=BINARY 'You look a little dazed.  Have you been reading our legal documents?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 2882,'Этот сундук заперт!' FROM `quest_template` b WHERE b.`id`=2882 AND BINARY b.`requestitemstext`=BINARY 'This chest is locked!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 3161,'Прекрасно! Эти украшения отлично подойдут для моих исследований. Большое спасибо за помощь, $N.$B$BАх да, можно мне вернуть мой шлем?' FROM `quest_template` b WHERE b.`id`=3161 AND BINARY b.`offerrewardtext`=BINARY 'Perfect; these ornaments are perfect for my studies. Thanks so much for the help, $N.$B$BOh, can I get my helmet back?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 3161,'Возникли трудности?$B$BГаз\'рилльское украшение можно найти почти в любом уголке Танариса, $N. Продолжай поиски!' FROM `quest_template` b WHERE b.`id`=3161 AND BINARY b.`requestitemstext`=BINARY 'Are you having any trouble?$B$BYou can find Gahz\'ridian just about anywhere in Tanaris, $N, so keep looking!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 3362,'Они такие большие? Пожалуй, придётся пересмотреть план...$b$bНо свою часть уговора ты выполняешь, так что вот обещанное.' FROM `quest_template` b WHERE b.`id`=3362 AND BINARY b.`offerrewardtext`=BINARY 'They\'re that big? I might have to rethink my plan...$b$bBut you did hold up your end of the bargain, so here\'s what I promised.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 3362,'Я хотел бы повнимательнее рассмотреть тот кактус в долине... Так что оставь от него хоть что-нибудь целое, ладно?' FROM `quest_template` b WHERE b.`id`=3362 AND BINARY b.`requestitemstext`=BINARY 'I\'d like to take a closer look at that cactus in the valley... So leave some of it in one piece, will ya?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 3570,'Ты ведь понимаешь, к чему всё идёт, $N? Она не выживет... посмотри на неё. Лучшее, что она сейчас может сделать, — помочь нам найти лекарство от чумы. Вода, которую она пила, может дать нам подсказку. Она всё равно умрёт — так пусть перед смертью сделает что-нибудь благородное для нашего народа. Разве ты не согласен?' FROM `quest_template` b WHERE b.`id`=3570 AND BINARY b.`requestitemstext`=BINARY 'You know where this is leading, don\'t you, $N? There\'s no way she can survive... look at her. The best thing for her now is to aid us in finding a cure for the plague. This water she drank might have a clue that helps us figure out how. She\'s going to die anyway--she might as well die doing something noble for our people before she does. Don\'t you agree?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 3783,'Эти меха идеально подходят, $N. Отличное начало!' FROM `quest_template` b WHERE b.`id`=3783 AND BINARY b.`offerrewardtext`=BINARY 'These furs are perfect, $N. We\'re off to a great start here!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 3783,'У меня тут ещё много работы. Прошу, принеси меха как можно скорее!' FROM `quest_template` b WHERE b.`id`=3783 AND BINARY b.`requestitemstext`=BINARY 'I\'ve got lots to get started on here. Please get me those furs as soon as you can!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 4106,'Именно то, что мне нужно. Вот, возьми эти целебные мази для растений и очисти с их помощью Оскверненный лес от скверны. Мы не должны сдаваться, $n!' FROM `quest_template` b WHERE b.`id`=4106 AND BINARY b.`offerrewardtext`=BINARY 'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 4111,'Именно то, что мне нужно. Вот, возьми эти целебные мази для растений и очисти с их помощью Оскверненный лес от скверны. Мы не должны сдаваться, $n!' FROM `quest_template` b WHERE b.`id`=4111 AND BINARY b.`offerrewardtext`=BINARY 'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4441,'Надеюсь, вода освободит дух древня и позволит ему обрести покой.' FROM `quest_template` b WHERE b.`id`=4441 AND BINARY b.`requestitemstext`=BINARY 'The water will hopefully release the spirit of the ancient, and allow it to be at peace.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 4502,'Эти образцы отлично подойдут для моих исследований! Спасибо, $N! Обещаю, о результатах ты узнаешь раньше всех.' FROM `quest_template` b WHERE b.`id`=4502 AND BINARY b.`offerrewardtext`=BINARY 'These samples will be perfect for my studies! Thank you, $N! I promise, you\'ll be the first one I will tell about my findings.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4507,'Для наших исследований совершенно необходимо добыть мозг королевы. Судя по тому, что мы узнали, силитидами вполне может управлять некий злобный разум. Страшно даже представить, что способно повелевать столь коварными созданиями, $N.' FROM `quest_template` b WHERE b.`id`=4507 AND BINARY b.`requestitemstext`=BINARY 'Acquiring the queen\'s brain for our research is absolutely imperative.  From what we have learned, we believe that these silithid are quite possibly being controlled by a malign intelligence.  I shudder to think what could control something as insidious as the silithid, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4508,'Они глупцы, $N! Даже не пытаются оглядеться и заметить куда более серьёзную угрозу. Их слепая ненависть к Орде погубит нас всех. Я уж не знаю, как ещё доказать им опасность силитидов, разве что бросить в один из ульев, чтобы они всё увидели сами!$B$BПрости, у тебя для меня новости?' FROM `quest_template` b WHERE b.`id`=4508 AND BINARY b.`requestitemstext`=BINARY 'They are fools, $N!  They cannot even think to look around them for a greater threat; their irrational hatred of the Horde will be the end of us all.  I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!$B$BI\'m sorry, you bring news for my attention?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4808,'Тут холодно! Надеюсь, у тебя есть для меня одеяло!' FROM `quest_template` b WHERE b.`id`=4808 AND BINARY b.`requestitemstext`=BINARY 'It\'s cold up here! I hope you brought me a blanket!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4864,'Да... Рассказывай, какие новости.' FROM `quest_template` b WHERE b.`id`=4864 AND BINARY b.`requestitemstext`=BINARY 'Aye... Tell me the news.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 4901,'Вы встретились с Раншаллой?' FROM `quest_template` b WHERE b.`id`=4901 AND BINARY b.`offerrewardtext`=BINARY 'Did you meet up with Ranshalla?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4906,'Прошу, положи конец страданиям существ Оскверненного леса.' FROM `quest_template` b WHERE b.`id`=4906 AND BINARY b.`requestitemstext`=BINARY 'Please, put and end to the suffering of Felwood\'s creatures.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4984,'Заражённых чумой волков нужно убить, $N. Болезнь, которую они разносят, неизлечима. Я пытался... пытался, пока сам не стал жертвой чумы.' FROM `quest_template` b WHERE b.`id`=4984 AND BINARY b.`requestitemstext`=BINARY 'The wolves that are infected with the plague must be put down, $N.  The disease they carry cannot be cured.  I tried... I tried until I succumbed to the plague myself.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4985,'Я слышу твои шаги, $N. Я лишился зрения, но всё ещё чувствую происходящее вокруг. Страдания больных медведей закончены?' FROM `quest_template` b WHERE b.`id`=4985 AND BINARY b.`requestitemstext`=BINARY 'I hear your footsteps, $N.  My vision has faded from me, but I still am able to sense things around me.  Have you ended the misery of the disease-ridden grizzlies?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 4987,'От имени Круга Кенария приветствую тебя в этом анклаве, $C. Какое у тебя к нам дело?' FROM `quest_template` b WHERE b.`id`=4987 AND BINARY b.`requestitemstext`=BINARY 'On behalf of the Cenarion Circle, I bid you welcome to this enclave, $C. What business do you have with us?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5054,'Задание было непростым, но тебе удалось прекрасно справиться. И всё же не спеши думать, что на меня так легко произвести впечатление, $N.' FROM `quest_template` b WHERE b.`id`=5054 AND BINARY b.`offerrewardtext`=BINARY 'This was no easy task, yet you have excelled. But do not be too quick to think you have impressed me, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5055,'Да. Вот и ты. Теперь я верю, что ты истинный $C по своей природе. Даже самые свирепые создания тебя не остановили. Твоё возвращение превосходит мои ожидания.$b$bТеперь тебе по силам моя последняя просьба.' FROM `quest_template` b WHERE b.`id`=5055 AND BINARY b.`offerrewardtext`=BINARY 'Yes. You have returned. I believe now that you are a true $C by nature. You have faced the most ferocious of creatures and have returned, surpassing my expectations.$b$bYou are now ready for my final request.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5056,'Ты доказываешь и свою силу, и решимость. Впереди ещё много испытаний, но я уже показал тебе всё, что мог.$b$bУдачи, $N.' FROM `quest_template` b WHERE b.`id`=5056 AND BINARY b.`offerrewardtext`=BINARY 'You have proven both your strength and your determination. Many more challenges await you, but I have already shown you as much as I am able.$b$bGood luck, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5056,'Ши-Ротам смела и беспощадна. Она будет яростно защищать своих сородичей.' FROM `quest_template` b WHERE b.`id`=5056 AND BINARY b.`requestitemstext`=BINARY 'Shy-Rotam is bold and unforgiving; she will defend her kind with fervent enthusiasm.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5060,'Перед вами чрезвычайно прочный шкаф, надёжно запертый встроенным замком. Его передняя стенка покрыта глубокими царапинами и следами ударов. Вероятно, это следы многочисленных яростных, но безуспешных попыток раскрыть скрытые внутри тайны.$B$BЧтобы открыть этот шкаф, вам понадобится найти ключ.' FROM `quest_template` b WHERE b.`id`=5060 AND BINARY b.`requestitemstext`=BINARY 'An extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock.  The front of the cabinet is deeply scratched and marked.  This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.$B$BIf you are going to open this cabinet, you will need to find the key.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5082,'Я ценю твою помощь!' FROM `quest_template` b WHERE b.`id`=5082 AND BINARY b.`requestitemstext`=BINARY 'I appreciate your help!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5083,'Что это тебе удалось найти?' FROM `quest_template` b WHERE b.`id`=5083 AND BINARY b.`requestitemstext`=BINARY 'What is that you have found?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5086,'Мне нужно сравнить это с веществом из котла, и тогда, уверен, мы узнаем больше.' FROM `quest_template` b WHERE b.`id`=5086 AND BINARY b.`offerrewardtext`=BINARY 'I have to compare this to the substance you found in the cauldron, and then I\'m sure we\'ll know more.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5086,'Думаю, мы начинаем понимать, что здесь происходит, $N.' FROM `quest_template` b WHERE b.`id`=5086 AND BINARY b.`requestitemstext`=BINARY 'I think we are beginning to uncover what is happening here, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5087,'Посмотрим, что случится, когда фурболги племени Зимней Спячки не получат своей огненной воды!' FROM `quest_template` b WHERE b.`id`=5087 AND BINARY b.`requestitemstext`=BINARY 'We\'ll see what happens when the Winterfall don\'t get their firewater!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5097,'Как только башни будут отмечены, они станут первоочередными целями нашего наступления на Андорал. Думаю, когда мы обезвредим башни, появится главная угроза Андорала. После этого начнётся открытая борьба за город!$B$BТы здесь, чтобы доложить об успехе? Не забудь и сигнальный факел: мы должны следить за своим снаряжением.' FROM `quest_template` b WHERE b.`id`=5097 AND BINARY b.`requestitemstext`=BINARY 'Once the towers are marked, they\'ll become top priority targets for our attack on Andorhal. I suspect that once we neutralize the towers, the main threat of Andorhal will emerge. From that point on, we\'ll have a straight-up fight for control of the city!$B$Byou\'re back to report success, yes? Don\'t forget the beacon torch as well; we must maintain control of our materiel.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5098,'Как только башни будут отмечены, они станут первоочередными целями нашего наступления на Андорал. Думаю, когда мы обезвредим башни, появится главная угроза Андорала. После этого начнётся открытая борьба за город!$b$bТы здесь, чтобы доложить об успехе? Не забудь и сигнальный факел: мы должны следить за своим снаряжением.' FROM `quest_template` b WHERE b.`id`=5098 AND BINARY b.`requestitemstext`=BINARY 'Once the towers are marked, they\'ll become top priority targets for our attack on Andorhal. I suspect that once we neutralize the towers, the main threat of Andorhal will emerge. From that point on, we\'ll have a straight-up fight for control of the city!$b$bYou\'re back to report success, yes? Don\'t forget the beacon torch as well; we must maintain control of our materiel.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5121,'Огромное спасибо, $N. Надеюсь, теперь я смогу вернуться к исследованиям, не опасаясь засады. Прошу, прими это в награду.' FROM `quest_template` b WHERE b.`id`=5121 AND BINARY b.`offerrewardtext`=BINARY 'Thank you so much, $N. I hope to get back to my studies without worry that I will be ambushed. Please accept this as a reward.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5123,'Так, что это у тебя, $N?' FROM `quest_template` b WHERE b.`id`=5123 AND BINARY b.`requestitemstext`=BINARY 'Now, what\'s this, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5128,'Изумрудный Круг рад всем, $R. Чем могу помочь?' FROM `quest_template` b WHERE b.`id`=5128 AND BINARY b.`requestitemstext`=BINARY 'The Emerald Circle is friendly to all, $R. What can I do for you?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5155,'Отлично, $N! Их становится меньше, и мы можем усилить натиск.$b$bНу как тебе первая встреча с их силой? Они оказались такими сильными, как ты ожидал? Сильнее? Или они вообще не представляли для тебя опасности? Вот было бы здорово!$b$bПодробности твоих подвигов обсудим позже. Сейчас нужно сосредоточиться на другом.' FROM `quest_template` b WHERE b.`id`=5155 AND BINARY b.`offerrewardtext`=BINARY 'Good, $N! With their numbers weakening, we can further press them.$b$bHow was your first taste of their power? Were they as strong as you thought they would be? Stronger? Or perhaps they were no challenge for you at all. Wouldn\'t that be something?$b$bWe can discuss the details of your exploits later. There are other things we must focus on now.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5155,'Как идут твои сражения, $N? Знаю, кому-то отвратительно проливать кровь ради доказательства чести, но пойми: этим мы достигаем двух целей. Сокращая их численность, ты облегчаешь мне задачу, а взаимное уважение со временем сделает нас только сильнее.$B$BНадеюсь, ты понимаешь.' FROM `quest_template` b WHERE b.`id`=5155 AND BINARY b.`requestitemstext`=BINARY 'How goes your fight, $N? I know the shedding of blood as proof of honor can be disgusting to some, but you must understand that it serves two goals: you make my task easier by hurting their numbers, and we gain a respect for each other that will only make us stronger in times to come.$B$BI hope you understand.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5156,'Надеюсь, твои поиски идут хорошо, $N. Я ещё не заходил так далеко на север, но признаюсь, сама мысль о встрече с инферналом меня немного пугает. Ума у этих созданий нет, но вид всё равно устрашающий.' FROM `quest_template` b WHERE b.`id`=5156 AND BINARY b.`requestitemstext`=BINARY 'I hope your search goes well, $N. I haven\'t started heading that far north, but I will admit, the thought of crossing the path of an infernal at any point scares me just a little. The creatures are brainless, but still quite intimidating.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5157,'Это отлично подойдёт, $N.$b$bТеперь осталось не только оросить жаровни, но и очистить воду. Это не должно быть трудно — придётся лишь немного попутешествовать.$b$bНадеюсь, мы справимся быстро.' FROM `quest_template` b WHERE b.`id`=5157 AND BINARY b.`offerrewardtext`=BINARY 'This will do nicely, $N.$b$bNow all we have to do besides apply the waters to the braziers is to have it purified. That should not be difficult--it should only require a little travel.$b$bHopefully we can do this quickly.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5163,'Ха! Теперь они дважды подумают, прежде чем смеяться над моими идеями!$B$BСпасибо за помощь, $N. Без тебя мне бы так не повеселиться!' FROM `quest_template` b WHERE b.`id`=5163 AND BINARY b.`offerrewardtext`=BINARY 'Hah! They\'ll think twice before making fun of my ideas again!$B$BThanks for your help, $N. I couldn\'t have had so much fun without you!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5163,'Не терпится узнать, как отреагируют мои друзья!$B$BОни такого и представить не могут!' FROM `quest_template` b WHERE b.`id`=5163 AND BINARY b.`requestitemstext`=BINARY 'I can\'t wait to hear how my friends react!$B$BThey\'ll never expect it!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5245,'Я не хочу обсуждать прошлое высших эльфов, $N. Прошу, мне больно думать обо всём, что произошло... И о том, что уже ничего не исправить.' FROM `quest_template` b WHERE b.`id`=5245 AND BINARY b.`offerrewardtext`=BINARY 'The past of the high elves is something that I do not wish to discuss, $N. Please, it pains me to think of all that has happened... And that there is no way to make things right.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5245,'Зачем ты здесь?' FROM `quest_template` b WHERE b.`id`=5245 AND BINARY b.`requestitemstext`=BINARY 'Why have you come here?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5247,'С помощью этих элементов я могу сплавить осколки воедино... надеюсь, вернув им прежний вид.' FROM `quest_template` b WHERE b.`id`=5247 AND BINARY b.`offerrewardtext`=BINARY 'Using these elements, I can fuse the fragments together... to hopefully what they once were.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5252,'Это... то, о чём я думаю?' FROM `quest_template` b WHERE b.`id`=5252 AND BINARY b.`offerrewardtext`=BINARY 'Is that... what I think it is?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5252,'С твоего ухода прошло немало времени, $N. Как твои дела?' FROM `quest_template` b WHERE b.`id`=5252 AND BINARY b.`requestitemstext`=BINARY 'It has been some time since you left, $N. How have you fared?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5253,'Да, $R?' FROM `quest_template` b WHERE b.`id`=5253 AND BINARY b.`requestitemstext`=BINARY 'Yes, $R?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5283,'Вот и всё, $N. После этого назад пути не будет. Ещё не поздно стать мастером игрушек... то есть оружейником.$B$BУверен, ты примешь верное решение.' FROM `quest_template` b WHERE b.`id`=5283 AND BINARY b.`offerrewardtext`=BINARY 'This be it, $N. After this, there ain\'t no way to turn back. It\'s not too late to become a toy maker, er, weaponsmith.$B$BI trust ye\'ll make the right decision.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5283,'Ах, ничто не сравнится с загаром от горна. Сразу видно, у кого он лучше всего, — по следам от фартука.' FROM `quest_template` b WHERE b.`id`=5283 AND BINARY b.`requestitemstext`=BINARY 'Ah, ain\'t nothing like a good forge tan. Ye can tell who\'s got the really good tans by their apron lines.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5535,'Хорошая работа, $C. Спасибо за помощь. Духи обрели покой, и угроз, вызванных их тягой к тайной магии, стало меньше.$b$bУверен, обе стороны конфликта, терзающего Азерот, поймут, что ты выше подобных распрей.' FROM `quest_template` b WHERE b.`id`=5535 AND BINARY b.`offerrewardtext`=BINARY 'Well done, $C. Thank you for your help. The spirits are at peace, and the threats that their desire for the arcane draw have been lessened.$b$bI am sure that both sides of the conflict that ravishes Azeroth will see you are above such things.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5536,'Как идут твои сражения с сатирами, $c?$B$BОни оказались такими сильными, как ты ожидал? Сильнее? Или они ничто перед твоей мощью?' FROM `quest_template` b WHERE b.`id`=5536 AND BINARY b.`requestitemstext`=BINARY 'How goes your battle against the satyr, $c?$B$BAre they as strong as you thought? Stronger? Or perhaps they were nothing to your own might.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5863,'Как хорошо, что тебе удалось сделать это для меня, $N! Спасибо за помощь!' FROM `quest_template` b WHERE b.`id`=5863 AND BINARY b.`offerrewardtext`=BINARY 'I\'m so glad you were able to do this for me, $N! Thanks for your help!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 5863,'Я так волнуюсь! Прошу, будь осторожнее!' FROM `quest_template` b WHERE b.`id`=5863 AND BINARY b.`requestitemstext`=BINARY 'I\'m so worried! Please be careful!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5885,'Именно то, что мне нужно. Вот, возьми эти целебные мази для растений и очисти с их помощью Оскверненный лес от скверны. Мы не должны сдаваться, $n!' FROM `quest_template` b WHERE b.`id`=5885 AND BINARY b.`offerrewardtext`=BINARY 'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 5890,'Именно то, что мне нужно. Вот, возьми эти целебные мази для растений и очисти с их помощью Оскверненный лес от скверны. Мы не должны сдаваться, $n!' FROM `quest_template` b WHERE b.`id`=5890 AND BINARY b.`offerrewardtext`=BINARY 'This is exactly what I need. Here - take these plant salves and use them to reclaim Felwood from the corruption. We must persevere, $n!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 6021,'Отлично, с ним покончено! Надеюсь, его шайка тоже получила по заслугам!' FROM `quest_template` b WHERE b.`id`=6021 AND BINARY b.`offerrewardtext`=BINARY 'Great, you got him!  And I hope you taught his gang a lesson too!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 6026,'Могу заплатить половину вперёд, а вторую половину — когда дело будет сделано.' FROM `quest_template` b WHERE b.`id`=6026 AND BINARY b.`offerrewardtext`=BINARY 'I can pay you half up front and half when the job is done. ' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 6604,'Да, чем могу помочь?' FROM `quest_template` b WHERE b.`id`=6604 AND BINARY b.`offerrewardtext`=BINARY 'Aye, what can I do for you?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 7653,'Приятно иметь с тобой дело.$B$B$BИ перестань кривиться, $N.' FROM `quest_template` b WHERE b.`id`=7653 AND BINARY b.`offerrewardtext`=BINARY 'A pleasure doin\' business with ya.$B$B$BAnd $N, wipe that look of disgust off yer face.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 7654,'Приятно иметь с тобой дело.$B$BИ перестань кривиться, $N.' FROM `quest_template` b WHERE b.`id`=7654 AND BINARY b.`offerrewardtext`=BINARY 'A pleasure doin\' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 7655,'Приятно иметь с тобой дело.$B$BИ перестань кривиться, $N.' FROM `quest_template` b WHERE b.`id`=7655 AND BINARY b.`offerrewardtext`=BINARY 'A pleasure doin\' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 7656,'Приятно иметь с тобой дело.$B$BИ перестань кривиться, $N.' FROM `quest_template` b WHERE b.`id`=7656 AND BINARY b.`offerrewardtext`=BINARY 'A pleasure doin\' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 7657,'Приятно иметь с тобой дело.$B$BИ перестань кривиться, $N.' FROM `quest_template` b WHERE b.`id`=7657 AND BINARY b.`offerrewardtext`=BINARY 'A pleasure doin\' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 7658,'Приятно иметь с тобой дело.$B$BИ перестань кривиться, $N.' FROM `quest_template` b WHERE b.`id`=7658 AND BINARY b.`offerrewardtext`=BINARY 'A pleasure doin\' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 7659,'Приятно иметь с тобой дело.$B$BИ перестань кривиться, $N.' FROM `quest_template` b WHERE b.`id`=7659 AND BINARY b.`offerrewardtext`=BINARY 'A pleasure doin\' business with ya.$B$BAnd $N, wipe that look of disgust off yer face.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8352,'Ты... получилось! У тебя получилось, $N! Вот! Возьми. Это самый большой сундук, какой у нас был, и я наполнил его лучшими из наших находок.' FROM `quest_template` b WHERE b.`id`=8352 AND BINARY b.`offerrewardtext`=BINARY 'You... you did it! You did it, $N! Here! Take this. It\'s the biggest chest we had lying around and I filled it with some of the best stuff we found.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8365,'О, какое очарование, хоть ты и возишься дольше, чем я привыкла. Когда я почищу и приукрашу эти шляпы, партия принесёт мне немало денег. А поскольку я всегда готова наградить за хорошую работу, вот кое-что для тебя. Советую потратить часть на ванну, душа моя.' FROM `quest_template` b WHERE b.`id`=8365 AND BINARY b.`offerrewardtext`=BINARY 'Oh you\'re a darling, even if it did take you longer than I am accustomed to. This shipment should make me quite a bit of money once I\'ve cleaned and personalized these hats. And seeing as I\'m always willing to reward work that\'s well done, here\'s a little something for you. I suggest that you spend some of it on a bath sweetie.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 8365,'Все 20 шляп у тебя? Не верю, покажи! И чтобы они были в безупречном состоянии!' FROM `quest_template` b WHERE b.`id`=8365 AND BINARY b.`requestitemstext`=BINARY 'Do you have all 20 hats? I don\'t believe you, let me see them. They better be in pristine condition!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8411,'Вот нужные мне элементы. Теперь можно говорить.' FROM `quest_template` b WHERE b.`id`=8411 AND BINARY b.`offerrewardtext`=BINARY 'These be the elements I need. Now we talk.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 8460,'Продолжай, $N. Чтобы заслужить наше доверие, нужно проявить себя.' FROM `quest_template` b WHERE b.`id`=8460 AND BINARY b.`requestitemstext`=BINARY 'Keep at it, $N. If you are to earn our trust, you will need to prove yourself to us.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8463,'Отличная работа, $N.' FROM `quest_template` b WHERE b.`id`=8463 AND BINARY b.`offerrewardtext`=BINARY 'Excellent work, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 8463,'Украденные товары уже найдены?' FROM `quest_template` b WHERE b.`id`=8463 AND BINARY b.`requestitemstext`=BINARY 'Did you retrieve the stolen goods yet?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8464,'Спасибо за твой поступок, как бы ни было печально. Прими это в знак благодарности.$B$BПрошу, продолжай нам помогать, $N. У нас очень мало союзников, к которым можно обратиться, и без твоей помощи моё племя наверняка не справится с нависшими угрозами.' FROM `quest_template` b WHERE b.`id`=8464 AND BINARY b.`offerrewardtext`=BINARY 'Thank you for what you have done, as saddening as it is.  Accept this as a token of thanks.$B$BI would ask of you to please continue helping us, $N.  We have very few allies on which to call upon, and without your aid, the threats against my tribe would surely be too much for us to handle alone.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8466,'Отличная работа, $N! Я позабочусь о том, чтобы мой народ узнал о твоих деяниях.$B$BНе забывай приносить мне найденные перья. Я буду принимать их столько, сколько потребуется.' FROM `quest_template` b WHERE b.`id`=8466 AND BINARY b.`offerrewardtext`=BINARY 'Well done, $N! I will make sure that your deeds are known amongst my kind.$B$BRemember to bring any of the feathers you find to me. I will continue to accept them as long as necessary.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8467,'Отличная работа, $N! Я позабочусь о том, чтобы мой народ узнал о твоих деяниях.$B$BНе забывай приносить мне найденные перья. Я буду принимать их столько, сколько потребуется.' FROM `quest_template` b WHERE b.`id`=8467 AND BINARY b.`offerrewardtext`=BINARY 'Well done, $N!  I will make sure that your deeds are known amongst my kind.$B$BRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 8468,'У тебя есть что мне показать?' FROM `quest_template` b WHERE b.`id`=8468 AND BINARY b.`requestitemstext`=BINARY 'You have something to show me?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8472,'Отличная работа, $N. Наши магические святилища сейчас работают не в полную силу, и эти силовые ядра помогут восполнить нехватку энергии.' FROM `quest_template` b WHERE b.`id`=8472 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve done well, $N.  With our arcane sanctums not operating at full capacity, these power cores will go a long way in supplementing our needs.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8483,'Значит, дело сделано. Прекрасная работа.$B$BГенерал следопытов уже получил известие, и поверь: дворфы дорого заплатят за своё предательство.$B$BСегодня ты оказываешь своему народу огромную услугу, $N.' FROM `quest_template` b WHERE b.`id`=8483 AND BINARY b.`offerrewardtext`=BINARY 'So, the deed is done.  Excellent job.$B$BWord has been passed to the ranger general and believe me, the dwarves will pay dearly for their treason.$B$BYou\'ve been of great service to your people today, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 8483,'С незваным гостем покончено?' FROM `quest_template` b WHERE b.`id`=8483 AND BINARY b.`requestitemstext`=BINARY 'Did you take care of the intruder?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8486,'Спасибо, $N. Теперь, когда призраки у нас под контролем, можно послать кого-нибудь оценить ущерб. Надеюсь, ничего непоправимого не произошло.' FROM `quest_template` b WHERE b.`id`=8486 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N.  Now that we have the wraiths under control we can send someone in to assess the damage.  Hopefully this wasn\'t anything permanent.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 8895,'Спасибо, $N. Я ждал этого письма.' FROM `quest_template` b WHERE b.`id`=8895 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N.  I\'ve been expecting this letter.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9064,'Ты говоришь, эти два бездарных глупца подкупили тебя, чтобы ты мне солгал? Ты правильно поступаешь, обратившись ко мне, $N.' FROM `quest_template` b WHERE b.`id`=9064 AND BINARY b.`offerrewardtext`=BINARY 'You say those two incompetent fools bribed you to lie to me?  You\'ve done very well in coming to me, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9064,'Ради чего ты прерываешь мою лекцию, $c?' FROM `quest_template` b WHERE b.`id`=9064 AND BINARY b.`requestitemstext`=BINARY 'What calls for this interruption to my lecture, $c?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9066,'Отличная работа, $N. Не волнуйся, они не останутся в таком облике навсегда. Однако звание учеников они не вернут, пока не заслужат его заново.' FROM `quest_template` b WHERE b.`id`=9066 AND BINARY b.`offerrewardtext`=BINARY 'Excellent job, $N.  Don\'t worry, they\'re not stuck in that form permanently.  Their apprenticeship, however, won\'t be restored until they earn it back.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9066,'Моя просьба выполнена, $N?' FROM `quest_template` b WHERE b.`id`=9066 AND BINARY b.`requestitemstext`=BINARY 'Did you do what I asked of you, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9125,'Превосходно, $n! Этому точно найдётся применение.' FROM `quest_template` b WHERE b.`id`=9125 AND BINARY b.`offerrewardtext`=BINARY 'Most excellent, $n! These will definitely come to good use.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9125,'С первой связкой всё получилось превосходно, $n. Если у тебя есть ещё, я их приму. За каждую сданную связку ты получишь ещё один знак отличия.' FROM `quest_template` b WHERE b.`id`=9125 AND BINARY b.`requestitemstext`=BINARY 'You did an exemplary job on the first bundle, $n. If you have more, I will take them now. For every bundle that you turn in, I will reward you with another insignia.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9127,'Моя мечта стать профессиональным танцором на дискотеке Прибамбасска скоро сбудется! Продолжай в том же духе, $n.' FROM `quest_template` b WHERE b.`id`=9127 AND BINARY b.`offerrewardtext`=BINARY 'My dream of becoming a full-time dancer at the Gadgetzan disco is soon to become a reality! Keep up the good work, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9127,'В моём деле костяных обломков много не бывает, $n. Если накопятся лишние, приноси их мне, и я награжу тебя ещё одним знаком отличия.' FROM `quest_template` b WHERE b.`id`=9127 AND BINARY b.`requestitemstext`=BINARY 'A man in my line of work can never have too many bone fragments, $n. Whenever you have a surplus of fragments, bring them to me and I\'ll reward you with another insignia.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9128,'Я могу лишь указать тебе верный путь, $N.' FROM `quest_template` b WHERE b.`id`=9128 AND BINARY b.`requestitemstext`=BINARY 'I can only steer you in the right direction, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9129,'Ты оказываешь нам большую услугу, $n. Отличная работа!' FROM `quest_template` b WHERE b.`id`=9129 AND BINARY b.`offerrewardtext`=BINARY 'You perform a great service for us, $n. Well done!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9132,'И это всё? Может, в первый раз до тебя не дошло? Мне нужно БОЛЬШЕ!' FROM `quest_template` b WHERE b.`id`=9132 AND BINARY b.`offerrewardtext`=BINARY 'That\'s all you brought me? Maybe you didn\'t hear me the first time. I need MORE!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9132,'За каждую охапку обломков дам тебе знак отличия — чем больше, тем лучше. А теперь с глаз долой, пока я не разрубил тебя надвое!\n' FROM `quest_template` b WHERE b.`id`=9132 AND BINARY b.`requestitemstext`=BINARY 'For every armful of the scraps, I\'ll give you an insignia - the more the better. Now get out of my sight before I split you in two!\n' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9142,'Это твоя заслуженная награда, салага. А теперь не ной из-за заказов. Выполняй их или уничтожай.' FROM `quest_template` b WHERE b.`id`=9142 AND BINARY b.`offerrewardtext`=BINARY 'You earned this, scrub. Now, don\'t cry about your orders. Fill \'em or destroy \'em.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9165,'<Командир Метц берёт предписание и подписывает его.>$B$BПрекрасная работа, $N. Даже выдающаяся! Прими это в знак нашей признательности. Без всяких каламбуров, салага.' FROM `quest_template` b WHERE b.`id`=9165 AND BINARY b.`offerrewardtext`=BINARY '<Dispatch Commander Metz takes the writ and signs it.>$B$BExcellent work, $N. Outstanding even! Take this as a token of our appreciation. No pun intended, scrub.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9165,'Имя, звание и личный номер!' FROM `quest_template` b WHERE b.`id`=9165 AND BINARY b.`requestitemstext`=BINARY 'Name, rank and serial number!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9178,'Да, для ударного оружия пехоты они пригодятся.' FROM `quest_template` b WHERE b.`id`=9178 AND BINARY b.`offerrewardtext`=BINARY 'Yep, these will come in handy for the infantry\'s bashin\' weapons.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9178,'Выполняешь заказ, $C?' FROM `quest_template` b WHERE b.`id`=9178 AND BINARY b.`requestitemstext`=BINARY 'Filling a work order, $C?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9179,'Ещё доспехи для солдат! Замечательно, $N!' FROM `quest_template` b WHERE b.`id`=9179 AND BINARY b.`offerrewardtext`=BINARY 'More armor for the troops! Fantastic, $N!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9179,'Выполняешь заказ, $C?' FROM `quest_template` b WHERE b.`id`=9179 AND BINARY b.`requestitemstext`=BINARY 'Filling a work order, $C?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 9181,'Выполняешь заказ, $C?' FROM `quest_template` b WHERE b.`id`=9181 AND BINARY b.`requestitemstext`=BINARY 'Filling a work order, $C?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9182,'Они не такие большие, как я ожидал. Но уговор есть уговор.' FROM `quest_template` b WHERE b.`id`=9182 AND BINARY b.`offerrewardtext`=BINARY 'These aren\'t as huge as I expected. Regardless, a deal is a deal.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
