INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9203,'Без комментариев.$B$B<Караванщик Камнетес сердито смотрит на вас.>$B$BЯ сказал: без комментариев! А теперь с глаз долой!' FROM `quest_template` b WHERE b.`id`=9203 AND BINARY b.`offerrewardtext`=BINARY 'No comment.$B$B<Packmaster Stonebruiser glares at you.>$B$BI said no comment! Now get out of my sight!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
