INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9204,'Можно было найти этому другое применение, но ведь теперь уже поздно, верно? Теперь жалеть бесполезно, $N.' FROM `quest_template` b WHERE b.`id`=9204 AND BINARY b.`offerrewardtext`=BINARY 'You could have used this for something else, but you didn\'t, did you? No use crying about it now, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
