INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9205,'Ты правда не знаешь, зачем они нужны?$B$B<Караванщик Камнетес смеётся.>$B$BБудто я тебе расскажу!' FROM `quest_template` b WHERE b.`id`=9205 AND BINARY b.`offerrewardtext`=BINARY 'You really don\'t know what these are for?$B$B<Packmaster Stonebruiser laughs.>$B$BLike I\'m going to tell you! ' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
