INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 9809,'Спасибо, $N. Я старейшина Спореггара и должен заботиться о том, чтобы мой народ ни в чём не нуждался. Благодаря тебе моя задача стала гораздо проще.' FROM `quest_template` b WHERE b.`id`=9809 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N.  As Sporeggar\'s elder, I must ensure my people have adequate supplies.  You make my task that much easier.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
