INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 10002,'В лагере становится всё оживлённее. Твоё задание выполнено?' FROM `quest_template` b WHERE b.`id`=10002 AND BINARY b.`requestitemstext`=BINARY 'The activity in the camp continues to escalate. Have you carried out your mission?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 10003,'Чем дольше мы позволяем им готовиться, тем труднее будет их выкорчевать. Связной убит?' FROM `quest_template` b WHERE b.`id`=10003 AND BINARY b.`requestitemstext`=BINARY 'The longer we permit them to make preparations, the more difficult it will be to root them out. Have you killed the liaison?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
