INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 11151,'<Капитан внимательно выслушивает ваш доклад.>$B$BМы отомстили за Джеймса и его семью, но даже это не вернёт того, что было уничтожено.' FROM `quest_template` b WHERE b.`id`=11151 AND BINARY b.`offerrewardtext`=BINARY '<The captain listens to your report intently.>$B$BWe have avenged James and his family, but not even that can restore what was destroyed.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
