INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 11494,'Есть успехи?' FROM `quest_template` b WHERE b.`id`=11494 AND BINARY b.`requestitemstext`=BINARY 'Progress?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13410,'$N, возвращайся ко мне, когда поможешь захватить каждый из фортов!' FROM `quest_template` b WHERE b.`id`=13410 AND BINARY b.`requestitemstext`=BINARY '$N, return to me when you have aided in the capture of each of the forts!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13411,'Отличная работа, $n. Я почти слышал битвы у тех фортов. Жаль, не довелось увидеть их своими глазами!' FROM `quest_template` b WHERE b.`id`=13411 AND BINARY b.`offerrewardtext`=BINARY 'Nice work, $n. I could almost hear the battles waged at those forts. I wish I was there to see them!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13507,'Дело закончено?' FROM `quest_template` b WHERE b.`id`=13507 AND BINARY b.`requestitemstext`=BINARY 'Have you finished the deed?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13515,'Так и должно быть.' FROM `quest_template` b WHERE b.`id`=13515 AND BINARY b.`requestitemstext`=BINARY 'As it should be.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13518,'Их гордость так долго удерживала их в Аубердине, но никто не заслуживает столь жестокой участи.' FROM `quest_template` b WHERE b.`id`=13518 AND BINARY b.`requestitemstext`=BINARY 'Their pride kept them in Auberdine for this long, but none deserve such a cruel fate.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13522,'Побережье очищено?' FROM `quest_template` b WHERE b.`id`=13522 AND BINARY b.`requestitemstext`=BINARY 'Have you cleared the coast?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13542,'Не знаю, как тебя отблагодарить, $N. Теперь, когда мы поправимся, у нас будет шанс отвоевать руины.' FROM `quest_template` b WHERE b.`id`=13542 AND BINARY b.`offerrewardtext`=BINARY 'I cannot thank you enough, $N. Now we\'ll have a fighting chance to retake the ruins as soon as we are in better health.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13545,'Твои труды и благословение медведя помогли очистить моих братьев?' FROM `quest_template` b WHERE b.`id`=13545 AND BINARY b.`requestitemstext`=BINARY 'Have your efforts and the bear\'s blessing cleansed my brothers?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13546,'Спасибо, $N. Ты — герой для моего народа. Без тебя нас ждали бы безумие и смерть. Пусть дух медведя всегда хранит тебя.' FROM `quest_template` b WHERE b.`id`=13546 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N. You are a hero to my people. Without you, we would be doomed to madness and death. May the bear spirit always watch over you.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13546,'Сатир, отравляющий наши земли, повержен?' FROM `quest_template` b WHERE b.`id`=13546 AND BINARY b.`requestitemstext`=BINARY 'Have you defeated the satyr who poisons our lands?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13560,'Ну что, закончил, парень?' FROM `quest_template` b WHERE b.`id`=13560 AND BINARY b.`requestitemstext`=BINARY 'You done yet, boy?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13561,'Дело сделано?' FROM `quest_template` b WHERE b.`id`=13561 AND BINARY b.`requestitemstext`=BINARY 'Is it done?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13576,'Стихия огня необычна: беспорядочные атаки нередко лишь помогают ей распространиться... только сильнее разжигая пламя.$B$BМы поступим разумнее, $N. Мы справимся с ней как следует.' FROM `quest_template` b WHERE b.`id`=13576 AND BINARY b.`offerrewardtext`=BINARY 'The element of fire is unique in that attacking it indiscriminately can often lead it to spreading further... succeeding only in agitating its flames.$B$BWe are wiser than that, $N.  We are going to dispose of it properly.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13576,'Дело уже сделано, $N?' FROM `quest_template` b WHERE b.`id`=13576 AND BINARY b.`requestitemstext`=BINARY 'Is it done yet, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13578,'Благодарю тебя, $R. Скоро мои сородичи обретут покой.' FROM `quest_template` b WHERE b.`id`=13578 AND BINARY b.`offerrewardtext`=BINARY 'I thank you, $R. Soon my kin will rest.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13580,'Дело сделано, $N?' FROM `quest_template` b WHERE b.`id`=13580 AND BINARY b.`requestitemstext`=BINARY 'Is it done, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13581,'Хорошие новости, $N. Фурболги могут казаться всего лишь дикарями, но их связь с землёй уходит в глубокую древность, а их шаманам нет равных.' FROM `quest_template` b WHERE b.`id`=13581 AND BINARY b.`offerrewardtext`=BINARY 'This is fortunate news, $N.  The furbolg may seem little more than a savage race, but their ties to the land are ancient and their shamans are second to none.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13584,'Земля здесь неспокойна, $N. Пройдут годы, прежде чем в эти края вернётся покой.' FROM `quest_template` b WHERE b.`id`=13584 AND BINARY b.`requestitemstext`=BINARY 'The land is deeply unsettled, $N. It\'ll be years before calm returns to these parts.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13585,'Прекрасная работа, $N! Помощь Селенн в сдерживании вихря будет бесценна.' FROM `quest_template` b WHERE b.`id`=13585 AND BINARY b.`offerrewardtext`=BINARY 'Excellent job, $N!  Selenn\'s help in holding back the vortex will be invaluable.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13587,'Благодарю тебя, $N. Благодаря тебе я свободен. Теперь посмотрим, что мы можем сделать для твоего мира.' FROM `quest_template` b WHERE b.`id`=13587 AND BINARY b.`offerrewardtext`=BINARY 'I thank you, $N.  You\'ve given me my freedom.  Let\'s see what we can do for your world now.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13587,'Удалось найти, $N?' FROM `quest_template` b WHERE b.`id`=13587 AND BINARY b.`requestitemstext`=BINARY 'Did you find it, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13588,'Ход событий меняется в нашу пользу, $N. Теперь мы сможем не допустить дальнейших разрушений.$B$BНо работы впереди ещё много.' FROM `quest_template` b WHERE b.`id`=13588 AND BINARY b.`offerrewardtext`=BINARY 'We are turning the tides, $N.  We should be able to contain further damage.$B$BMuch work still remains to be done.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13588,'Дело сделано, $N? Боюсь, я долго не продержусь.' FROM `quest_template` b WHERE b.`id`=13588 AND BINARY b.`requestitemstext`=BINARY 'Is it done, $N? I fear I cannot hold for much longer.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13595,'Ваши жизни и так коротки. Зачем вы тратите их, убивая друг друга?' FROM `quest_template` b WHERE b.`id`=13595 AND BINARY b.`requestitemstext`=BINARY 'Your lives are all so short. Why is it that you insist on squandering them by killing each other?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13596,'Отличная работа, $N. Дай мне немного времени изучить доставленные тобой чертежи.' FROM `quest_template` b WHERE b.`id`=13596 AND BINARY b.`offerrewardtext`=BINARY 'Excellent job, $N. Now give me a moment to examine the plans you\'ve brought me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13596,'Чертежи уже у тебя, $N?' FROM `quest_template` b WHERE b.`id`=13596 AND BINARY b.`requestitemstext`=BINARY 'Have you obtained the plans yet, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13624,'Этого совершенно недостаточно, $C. Мы вот-вот потеряем позиции, а тогда с этим участком леса будет покончено.$B$BНужно удержать рубеж!' FROM `quest_template` b WHERE b.`id`=13624 AND BINARY b.`requestitemstext`=BINARY 'That\'s not nearly enough, $C. We\'re about to lose our ground here and when that happens, it\'s all over for this section of the forest.$B$BWe must hold the line here!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13698,'Время на исходе, $N.' FROM `quest_template` b WHERE b.`id`=13698 AND BINARY b.`requestitemstext`=BINARY 'Time\'s running out, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13849,'Чего ты ждёшь? Туши огонь!' FROM `quest_template` b WHERE b.`id`=13849 AND BINARY b.`requestitemstext`=BINARY 'What are you waiting for? Put those fires out!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13853,'Мы спасены! Столько уже сбито, что с остальными мы справимся.$B$BНе знаю, как тебя отблагодарить, $N.' FROM `quest_template` b WHERE b.`id`=13853 AND BINARY b.`offerrewardtext`=BINARY 'We\'re saved! You\'ve shot down enough of them that we should be able to handle the rest.$B$BI cannot thank you enough, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13853,'Они всё ещё нас бомбят. Прошу, $N, сбей их!' FROM `quest_template` b WHERE b.`id`=13853 AND BINARY b.`requestitemstext`=BINARY 'There\'s still more of them bombing us. Please, $N, shoot them down!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13867,'Отличная работа, $N.$B$BФурболги постоянно нам угрожают. Надеюсь, это удержит их в стороне ещё ненадолго.' FROM `quest_template` b WHERE b.`id`=13867 AND BINARY b.`offerrewardtext`=BINARY 'Well done, $N.$B$BWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13891,'Боюсь и спросить, $n. Артефакт уничтожен? А что с его стражем?' FROM `quest_template` b WHERE b.`id`=13891 AND BINARY b.`requestitemstext`=BINARY 'I\'m afraid to ask, $n. Is the artifact destroyed? What about its guardian?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13892,'Разведка завершена, $N?' FROM `quest_template` b WHERE b.`id`=13892 AND BINARY b.`requestitemstext`=BINARY 'Have you completed your scouting mission, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13900,'Отличная работа, $N. К сожалению, битва ещё далека от завершения.' FROM `quest_template` b WHERE b.`id`=13900 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve done well, $N. Unfortunately the battle is far from over.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13900,'Приветствую, $N.' FROM `quest_template` b WHERE b.`id`=13900 AND BINARY b.`requestitemstext`=BINARY 'Hail, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13909,'<Археолог Грофф копается в обломках.>$B$BМ-да, почти всё здесь выглядит так, будто на этом топтались, сидели или вымачивали в сортире. Но прикроем сверху соломой — и сойдёт.$B$BСкажи, $N, ты считаешь себя архитектором?' FROM `quest_template` b WHERE b.`id`=13909 AND BINARY b.`offerrewardtext`=BINARY '<Archaeologist Groff picks through the wreckage.>$B$BWell, not much here that don\'t look stepped on, sat on, or soaked in a toilet. But toss some thatch on top and it\'ll do.$B$BTell me, $N, do you consider yourself an architect?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13909,'Ну что, как водичка?' FROM `quest_template` b WHERE b.`id`=13909 AND BINARY b.`requestitemstext`=BINARY 'Wet enough for ya?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13913,'Спасибо, $N. Мрачные вести ты приносишь об остальных гномах из команды, но хотя бы нескольких удалось спасти. За это я благодарен.' FROM `quest_template` b WHERE b.`id`=13913 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N. Grim news you bring of the rest of the gnome team, but at least you managed to save a few. For that I am grateful.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13918,'Да, да, это оно! Посмотри: размеры выемки в точности совпадают с древним диском, как я и предполагал. Вот твоя награда, $N — вполне заслуженная.$B$BГотовишься встретиться с историей лицом к лицу? Послушаем, что скажут древние!' FROM `quest_template` b WHERE b.`id`=13918 AND BINARY b.`offerrewardtext`=BINARY 'Why yes, yes, this is it! See here, the slot is the exact dimensions of the ancient disc, just as I\'d surmised. Here\'s your reward, $N - you\'ve earned it.$B$BAre you ready to meet history face to face? Let\'s see what the ancients have to say!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13925,'Интересно... Похоже, наше лекарство убережёт зверей, но ты говоришь, что там было что-то ещё? Какая-то злобная сущность?$B$BЭто хороший знак, $N. Кто бы за этим ни стоял, ему это не по нраву. Значит, мы на верном пути.' FROM `quest_template` b WHERE b.`id`=13925 AND BINARY b.`offerrewardtext`=BINARY 'Interesting... It sounds like our cure will keep the wildlife safe, but you say you saw something else? Some kind of angry presence?$B$BThis is a good sign, $N. Whatever is behind this isn\'t happy, and that means we\'re on to something.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 13925,'Сила саженца, который ты несёшь, растёт даже сейчас, пока мы говорим. Жизнь возрождается, $n. Получилось?' FROM `quest_template` b WHERE b.`id`=13925 AND BINARY b.`requestitemstext`=BINARY 'The sapling you carry grows in power even as we speak. Life is regenerative, $n. Did it work?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13940,'Как раз вовремя, $N. Не знаю, сколько ещё мы продержимся.' FROM `quest_template` b WHERE b.`id`=13940 AND BINARY b.`offerrewardtext`=BINARY 'You\'re just in time, $N.  I don\'t know how much longer we can hold. ' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 13964,'Рад наконец познакомиться, $N. Я наслышан о твоих делах и, должен сказать, впечатлён!$B$BПоделишься с нами своим мастерством?' FROM `quest_template` b WHERE b.`id`=13964 AND BINARY b.`offerrewardtext`=BINARY 'Good to finally meet you, $N. I\'ve heard all about what you\'ve been up to and let me just say that I\'m impressed!$B$BThink you can lend us your expertise?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14005,'Удалось найти источник скверны?' FROM `quest_template` b WHERE b.`id`=14005 AND BINARY b.`requestitemstext`=BINARY 'Did you find the source of the corruption?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14093,'С этими $r покончено?' FROM `quest_template` b WHERE b.`id`=14093 AND BINARY b.`requestitemstext`=BINARY 'Have the $r been dealt with?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14098,'Всё получилось, $n?' FROM `quest_template` b WHERE b.`id`=14098 AND BINARY b.`requestitemstext`=BINARY 'Have you succeeded, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14134,'Как идёт обработка дерева? Надо видеть, что эта штука делает с брокколи!' FROM `quest_template` b WHERE b.`id`=14134 AND BINARY b.`requestitemstext`=BINARY 'How\'s the wood processing going? You should see what that thing does to broccoli!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14154,'Уже получается! Осторожнее, а то мы его потеряем!' FROM `quest_template` b WHERE b.`id`=14154 AND BINARY b.`requestitemstext`=BINARY 'Getting there!  Careful or we\'ll lose him!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14193,'Наполнив его соком дынь, вы промываете глаза у древнего источника.$b$bОткрыв глаза, вы видите духов древних эльфов, всё ещё преданно совершающих обряды во славу своей богини.' FROM `quest_template` b WHERE b.`id`=14193 AND BINARY b.`offerrewardtext`=BINARY 'After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.$b$bUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14217,'Жаровня безмолвно ожидает подношения.' FROM `quest_template` b WHERE b.`id`=14217 AND BINARY b.`requestitemstext`=BINARY 'The brazier silently awaits an offering.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14225,'Нельзя позволить Пылающему Клинку осуществить свой замысел!' FROM `quest_template` b WHERE b.`id`=14225 AND BINARY b.`requestitemstext`=BINARY 'The Burning Blade must not be allowed to succeed with their plan!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14232,'Что это у тебя, $c?' FROM `quest_template` b WHERE b.`id`=14232 AND BINARY b.`requestitemstext`=BINARY 'What have you there, $c?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14252,'Как идут поиски хвостов, $n?' FROM `quest_template` b WHERE b.`id`=14252 AND BINARY b.`requestitemstext`=BINARY 'How\'s the search for tail coming, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14256,'Теперь ты понимаешь, $R. Это дело требует серьёзного отношения.' FROM `quest_template` b WHERE b.`id`=14256 AND BINARY b.`requestitemstext`=BINARY 'Now you see, $R. This is not a matter to be taken lightly.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14264,'Скажи мне, малёк. Моя просьба выполнена?' FROM `quest_template` b WHERE b.`id`=14264 AND BINARY b.`requestitemstext`=BINARY 'Tell me, minnow. Have you done as I asked?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14265,'$N! Где тебя носило?$B$BВпрочем... хорошо, что с тобой всё в порядке.' FROM `quest_template` b WHERE b.`id`=14265 AND BINARY b.`offerrewardtext`=BINARY '$N!  Where have you been?$B$BAnyway... it\'s great to see you in one piece.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14268,'Неужели...?' FROM `quest_template` b WHERE b.`id`=14268 AND BINARY b.`requestitemstext`=BINARY 'Could it be....?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14301,'Прошу, прими эту награду за свои подвиги, $N.$B$BБлагодаря тебе у нас есть драгоценное время!' FROM `quest_template` b WHERE b.`id`=14301 AND BINARY b.`offerrewardtext`=BINARY 'Please accept this reward for your heroic accomplishments, $N.$B$BYou have bought us precious time!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14305,'Прекрасные образцы, $R.$B$BЯ немедленно начну исследования.' FROM `quest_template` b WHERE b.`id`=14305 AND BINARY b.`offerrewardtext`=BINARY 'These are fine specimens, $R.$B$BI shall commence my studies immediately.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14305,'Необходимые мне образцы собраны?' FROM `quest_template` b WHERE b.`id`=14305 AND BINARY b.`requestitemstext`=BINARY 'Have you collected the samples I require?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14306,'От имени самих Пустошей благодарю тебя, $R.$B$BПрими нашу глубочайшую признательность.' FROM `quest_template` b WHERE b.`id`=14306 AND BINARY b.`offerrewardtext`=BINARY 'On behalf of Desolace herself, I thank you, $R.$B$BPlease accept our deepest gratitude.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14310,'Не беспокойся о последствиях горения всех этих химикатов в лаборатории. Волосы отрастут!' FROM `quest_template` b WHERE b.`id`=14310 AND BINARY b.`requestitemstext`=BINARY 'Don\'t worry about the residual effects of all those burning chemicals in the lab. Hair grows back!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14312,'Не бойся, $R. Я не причиню тебе вреда.' FROM `quest_template` b WHERE b.`id`=14312 AND BINARY b.`offerrewardtext`=BINARY 'Be not afraid, $R. I mean you no harm.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14314,'Благодарю тебя, $R.$B$BБез твоей помощи наше племя могло бы погибнуть.' FROM `quest_template` b WHERE b.`id`=14314 AND BINARY b.`offerrewardtext`=BINARY 'I thank you, $R.$B$BOur tribe may not have survived without your aid.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14314,'Мой народ свободен, $R?' FROM `quest_template` b WHERE b.`id`=14314 AND BINARY b.`requestitemstext`=BINARY 'Have my people been freed, $R?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14316,'Удалось найти наши вещи, $N?' FROM `quest_template` b WHERE b.`id`=14316 AND BINARY b.`requestitemstext`=BINARY 'Were you able to find our belongings, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14318,'Зачем ты вмешиваешься в дела кентавров, $R?' FROM `quest_template` b WHERE b.`id`=14318 AND BINARY b.`offerrewardtext`=BINARY 'Why is it that you meddle in centaur affairs, $R?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14318,'Чего тебе?' FROM `quest_template` b WHERE b.`id`=14318 AND BINARY b.`requestitemstext`=BINARY 'What do you want?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14325,'Очень хорошо, $R.$B$BПока нам этого хватит.' FROM `quest_template` b WHERE b.`id`=14325 AND BINARY b.`offerrewardtext`=BINARY 'Very good, $R.$B$BThis will sustain us for now.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14325,'Еда для моего клана у тебя, $R?' FROM `quest_template` b WHERE b.`id`=14325 AND BINARY b.`requestitemstext`=BINARY 'Have you brought food for my clan, $R?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14328,'Все мои сыновья убиты... мой клан разорён...$B$BБудь я молод, я бы разорвал тебя на части!$B$BУходи... убей меня или оставь наедине с горем, $R.' FROM `quest_template` b WHERE b.`id`=14328 AND BINARY b.`offerrewardtext`=BINARY 'My sons all slain... my clan in ruins....$B$BWere I in my youth, I would tear you limb from limb!$B$BGo now... kill me or leave me to mourn alone, $R.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14330,'Я могу безопасно уйти, $R?' FROM `quest_template` b WHERE b.`id`=14330 AND BINARY b.`offerrewardtext`=BINARY 'Is it safe for me to leave, $R?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14357,'Статуя застыла в ожидании.' FROM `quest_template` b WHERE b.`id`=14357 AND BINARY b.`requestitemstext`=BINARY 'The statue stands expectantly.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14358,'Жаровня безмолвно ожидает подношения.' FROM `quest_template` b WHERE b.`id`=14358 AND BINARY b.`requestitemstext`=BINARY 'The brazier silently awaits an offering.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14359,'Жаровня безмолвно ожидает подношения.' FROM `quest_template` b WHERE b.`id`=14359 AND BINARY b.`requestitemstext`=BINARY 'The brazier silently awaits an offering.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14363,'Нельзя позволить Пылающему Клинку осуществить свой замысел!' FROM `quest_template` b WHERE b.`id`=14363 AND BINARY b.`requestitemstext`=BINARY 'The Burning Blade must not be allowed to succeed with their plan!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14364,'Благодаря тебе удалось избежать серьёзного кризиса, $C.$B$BЗадержись этот призыв ещё немного, демон стал бы слишком силён для наших немногочисленных бойцов.$B$BПрошу, прими этот дар в благодарность за службу.' FROM `quest_template` b WHERE b.`id`=14364 AND BINARY b.`offerrewardtext`=BINARY 'You diverted what would have been a serious crisis, $C.$B$BIf that summoning was delayed just a bit longer, the demon would have become far too powerful for our small forces here to contend with.$B$BPlease accept this gift as our thanks for your service.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14378,'Ну что, $C? Этот кретин нашёлся?' FROM `quest_template` b WHERE b.`id`=14378 AND BINARY b.`requestitemstext`=BINARY 'Well, $C? Did yeh find the cretin?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14381,'Твои деяния по-прежнему впечатляют меня, $N.$B$BПрошу, прими этот дар от имени Круга Кенария.' FROM `quest_template` b WHERE b.`id`=14381 AND BINARY b.`offerrewardtext`=BINARY 'Your deeds continue to impress me, $N.$B$BPlease accept this gift on behalf of the Cenarion Circle.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14381,'С нагами в нашей расселине покончено, $N?' FROM `quest_template` b WHERE b.`id`=14381 AND BINARY b.`requestitemstext`=BINARY 'Have you dealt with the naga in our crevasse, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 14393,'Отличная работа, $N!$B$BПокончим с этим!' FROM `quest_template` b WHERE b.`id`=14393 AND BINARY b.`offerrewardtext`=BINARY 'Well done, $N!$B$BLet us finish this!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14408,'Думаю, архивы где-то рядом, $N. Найди чертежи!' FROM `quest_template` b WHERE b.`id`=14408 AND BINARY b.`requestitemstext`=BINARY 'I suspect the archives are close, $N. Locate those plans!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14452,'Вперёд, $n! Мы никого не пропустим. Врывайся в самую гущу и раскидывай их во все стороны!' FROM `quest_template` b WHERE b.`id`=14452 AND BINARY b.`requestitemstext`=BINARY 'Get in there, $n! We won\'t let any past. I want you in the midst of them, scattering them left and right!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14459,'Я отсюда вижу ещё многих из них, $n. Нужно уничтожить больше.' FROM `quest_template` b WHERE b.`id`=14459 AND BINARY b.`requestitemstext`=BINARY 'I can still see many of them from here, $n. More should fall.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 14491,'Земля довольна?' FROM `quest_template` b WHERE b.`id`=14491 AND BINARY b.`requestitemstext`=BINARY 'Is the land satisfied?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 20440,'Лапы и когти у тебя, $N?' FROM `quest_template` b WHERE b.`id`=20440 AND BINARY b.`requestitemstext`=BINARY 'Do you have the paws and talons, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24469,'Сколько их у тебя?' FROM `quest_template` b WHERE b.`id`=24469 AND BINARY b.`requestitemstext`=BINARY 'How many of \'em did ya get?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24470,'Ну, чего ждёшь, $c?' FROM `quest_template` b WHERE b.`id`=24470 AND BINARY b.`requestitemstext`=BINARY 'Well, what\'re ye waitin\' for, $c?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24471,'Спасибо за помощь, $n.' FROM `quest_template` b WHERE b.`id`=24471 AND BINARY b.`requestitemstext`=BINARY 'Thanks for yer help, $n.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24592,'Осторожнее, $N.' FROM `quest_template` b WHERE b.`id`=24592 AND BINARY b.`requestitemstext`=BINARY 'Careful, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24616,'Дело сделано, $N?' FROM `quest_template` b WHERE b.`id`=24616 AND BINARY b.`requestitemstext`=BINARY 'Is it done, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24639,'Сила — не главное в победе над врагом и уж точно не главное, если хочешь выжить. В бою важен баланс. Всему своё время и место.' FROM `quest_template` b WHERE b.`id`=24639 AND BINARY b.`requestitemstext`=BINARY 'Strength isn\'t da end all of defeating ya enemy, and it most certainly isn\'t tha end all of stayin\' alive. Fightin\' is about balance. Everytin has its time and place.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24641,'Вряд ли с ними будет трудно, дружище, но если не будешь проворно двигаться, они тебе все лодыжки исцарапают.' FROM `quest_template` b WHERE b.`id`=24641 AND BINARY b.`requestitemstext`=BINARY 'I doubt dey too much of a challenge, mon, but they\'ll still claw up ya ankles if ya don\'t stay quick footed.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 24642,'А ты неплохо справляешься. Когда-нибудь тебе не будет равных.' FROM `quest_template` b WHERE b.`id`=24642 AND BINARY b.`offerrewardtext`=BINARY 'Ya handle yerself quite well. Ya gonna be quite powerful some day.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24697,'Брось мясо, а потом заманивай динозавров за собой в яму. Всё просто!' FROM `quest_template` b WHERE b.`id`=24697 AND BINARY b.`requestitemstext`=BINARY 'Throw the meat, then let the dinosaurs chase you into the pit. Easy as that!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24703,'Твоё первое задание простое, но почему-то до сих пор не выполнено. Выслушай меня и стань моим оруженосцем.' FROM `quest_template` b WHERE b.`id`=24703 AND BINARY b.`requestitemstext`=BINARY 'Your first quest is a simple one, yet it somehow remains unfinished. Endure my words and become my squire.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 24705,'Наш долг исполнен. И всё же меня тревожит, что нынешние люди не слишком-то признательны... Быть может, завтра нам воздадут должную благодарность.$B$BА теперь в седло. Нас ждут новые приключения!' FROM `quest_template` b WHERE b.`id`=24705 AND BINARY b.`offerrewardtext`=BINARY 'Our duty is fulfilled. Even so, it troubles me that the people of today are less than gracious... Perhaps tomorrow we shall experience proper thankfulness.$B$BNow we must ride. More adventures await!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24706,'Мы ещё не закончили молитвы. Мне пойти с тобой?' FROM `quest_template` b WHERE b.`id`=24706 AND BINARY b.`requestitemstext`=BINARY 'We have not completed our prayers. Shall I join you?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24722,'Да, $N?' FROM `quest_template` b WHERE b.`id`=24722 AND BINARY b.`requestitemstext`=BINARY 'Yes, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
