INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 24777,'Неплохо, дружище. Движения в бою у тебя естественные — похоже, к этому есть талант.$B$BКонечно, кое-что ещё нужно подправить, но здесь мы с этим разберёмся, а заодно я научу тебя новым приёмам.' FROM `quest_template` b WHERE b.`id`=24777 AND BINARY b.`offerrewardtext`=BINARY 'Not bad, mon. Ya have a natural flow to ya attacks - you may have a talent for dis.$B$BSome rough edges ta be sure, but we\'ll get dose ironed out here and I\'ll teach ya a few new tings as we go.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
