INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24799,'Правда ли, что тебе удалось восстановить Кель\'Делар?' FROM `quest_template` b WHERE b.`id`=24799 AND BINARY b.`requestitemstext`=BINARY 'Is it true that you have restored Quel\'Delar?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24852,'Слишком мало наших вернулось, $n. Возвращайся и освободи больше людей. Будь храбрее!' FROM `quest_template` b WHERE b.`id`=24852 AND BINARY b.`requestitemstext`=BINARY 'Not enough have returned, $n. Return and free more of our peopple. Be brave!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24861,'Не робей, $n. Для меня честь, что именно ты принесёшь последнее подношение.' FROM `quest_template` b WHERE b.`id`=24861 AND BINARY b.`requestitemstext`=BINARY 'Do not be shy, $n. I am honored to have you lay the final offering.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24863,'Что там происходит?' FROM `quest_template` b WHERE b.`id`=24863 AND BINARY b.`requestitemstext`=BINARY 'What\'s the story out there?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 24913,'Я тронут, $N. Пророк Велен пребывал в строжайшем уединении. Он не смел тратить силы ни на что, кроме подготовки к предсказанному им последнему противостоянию.$B$BИ всё же он явился сюда лично, чтобы утешить одну-единственную умирающую душу.$B$BЯ должен поблагодарить и тебя: с твоей помощью я сделал последнюю попытку утешить друга. Мои исследования продолжатся... и я надеюсь, что Магтур по-прежнему будет присматривать за мной.' FROM `quest_template` b WHERE b.`id`=24913 AND BINARY b.`offerrewardtext`=BINARY 'I am moved, $N. Prophet Velen has been in closely guarded seclusion. He has dared not waste his energy on anything save preparing for the final confrontation he has foretold.$B$BAnd yet, he came here, in person, to comfort a single dying soul.$B$BI must thank you as well, for helping me make my last effort to comfort my friend. My research will continue... and I hope that Magtoor will continue to watch over me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24930,'Ну, что такое, $n?' FROM `quest_template` b WHERE b.`id`=24930 AND BINARY b.`requestitemstext`=BINARY 'What is it then, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 24944,'Ко мне на холм один за другим поднимаются раненые, способные идти, $n. Полагаю, это твоих рук дело? Отличная работа!' FROM `quest_template` b WHERE b.`id`=24944 AND BINARY b.`offerrewardtext`=BINARY 'A steady stream of the walking wounded have come up the hill to see me, $n. I trust that was your work? Well done!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24951,'Не вижу с тобой никакого жука, приятель.' FROM `quest_template` b WHERE b.`id`=24951 AND BINARY b.`requestitemstext`=BINARY 'I don\'t see any bug with you, pal.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24953,'Обвала я не слышал, приятель! Попробуй ещё!' FROM `quest_template` b WHERE b.`id`=24953 AND BINARY b.`requestitemstext`=BINARY 'I didn\'t hear no cave-ins, pal! Try again!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24961,'Вы уже поговорили? Ей нужно показать правду.' FROM `quest_template` b WHERE b.`id`=24961 AND BINARY b.`requestitemstext`=BINARY 'Have you spoken with her yet?  She needs to be shown the truth.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 24974,'О, муки одиночества невыносимы!' FROM `quest_template` b WHERE b.`id`=24974 AND BINARY b.`requestitemstext`=BINARY 'Oh, the pain of loneliness is too much to bear!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 24990,'Отличная работа, $N, и я благодарю тебя за старания.' FROM `quest_template` b WHERE b.`id`=24990 AND BINARY b.`offerrewardtext`=BINARY 'You have done well, $N and I thank you for your efforts.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25013,'Ах, этот яд прекрасно подойдёт, $N. Всё остальное уже добавлено в мою смесь и уварено. Спасибо, $c!' FROM `quest_template` b WHERE b.`id`=25013 AND BINARY b.`offerrewardtext`=BINARY 'Ah, this venom will do perfectly, $N.  Everything else has been added to my concoction and boiled down.  Thank you, $c!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25013,'Удалось добыть яд Злобного ночного кругопряда, $N? Это последний компонент, необходимый для проверки моего опыта.' FROM `quest_template` b WHERE b.`id`=25013 AND BINARY b.`requestitemstext`=BINARY 'Do you have some venom from a Vicious Night Web Spider yet, $N?  It\'s the final component I need in order to test my experiment.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25034,'А, $n! Я как раз расхваливал тебя генералу. Ещё раз спасибо за спасение моей жизни.' FROM `quest_template` b WHERE b.`id`=25034 AND BINARY b.`offerrewardtext`=BINARY 'Ah, $n! I\'ve been talking you up to the General here. Thank you again for saving my life.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25050,'Чего мы ждём, глупышка! Мы ещё не закончили! Нужно отправляться!' FROM `quest_template` b WHERE b.`id`=25050 AND BINARY b.`requestitemstext`=BINARY 'Let\'s not wait around, silly! We weren\'t done yet! We\'ve gotta get out there!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25065,'Отличная работа, $N. Содержимое этого сундука наверняка значительно пополнит знания Гномрегана. Думаю, тебе полагается награда.' FROM `quest_template` b WHERE b.`id`=25065 AND BINARY b.`offerrewardtext`=BINARY 'Well done, $N. The contents of this chest are sure to advance Gnomeregan\'s knowledge base significantly. I believe you\'ve earned a reward.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25065,'Будь осторожнее с содержимым сундука.' FROM `quest_template` b WHERE b.`id`=25065 AND BINARY b.`requestitemstext`=BINARY 'Do be careful with the contents of the chest.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25066,'Что ты тут делаешь? Поднимайся наверх и сбивай их!' FROM `quest_template` b WHERE b.`id`=25066 AND BINARY b.`requestitemstext`=BINARY 'What are you doing back here? Get up there and shoot them down!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25067,'Хватит тратить моё время. Входи и сражайся!' FROM `quest_template` b WHERE b.`id`=25067 AND BINARY b.`requestitemstext`=BINARY 'Stop wasting my time. Enter and fight!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25094,'Хватит тратить моё время. Входи и сражайся!' FROM `quest_template` b WHERE b.`id`=25094 AND BINARY b.`requestitemstext`=BINARY 'Stop wasting my time. Enter and fight!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25095,'Хватит тратить моё время. Входи и сражайся!' FROM `quest_template` b WHERE b.`id`=25095 AND BINARY b.`requestitemstext`=BINARY 'Stop wasting my time. Enter and fight!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25126,'Хм-м, неплохо, $n. Только не зазнавайся... на своём пути ты ещё встретишь противников посерьёзнее кабанов.$b$bИ всё же ты достойно проявляешь себя. Следующее испытание будет куда опаснее, так что тебе понадобится дополнительная защита.' FROM `quest_template` b WHERE b.`id`=25126 AND BINARY b.`offerrewardtext`=BINARY 'Hmmm, not bad, $n. But don\'t let it get to your head...you\'ll fight tougher than boars in your career.$b$bNonetheless, you\'ve proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you\'ll need some extra protection.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25126,'Надеюсь, ты здесь не для того, чтобы убедить меня, будто задание выполнено, $n? Нет, конечно нет. Я о тебе лучшего мнения.' FROM `quest_template` b WHERE b.`id`=25126 AND BINARY b.`requestitemstext`=BINARY 'I hope you haven\'t returned to try and convince me that you have completed your task, $n? No, of course not. I would think better of you.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25127,'Из схваток со скорпидами нужно извлечь важный урок. И самый маленький, и самый большой противник может тебя погубить. В жестоком бою к гибели может привести что угодно.$b$bМне больше нечему тебя учить, $n. Ты хорошо справляешься, и я с интересом буду следить за твоими успехами.' FROM `quest_template` b WHERE b.`id`=25127 AND BINARY b.`offerrewardtext`=BINARY 'There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.$b$bI have no more to teach you, $n. You have done well, and I will watch your progress with interest.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25132,'Задание выполнено, $n? Медальон Пылающего Клинка у тебя?' FROM `quest_template` b WHERE b.`id`=25132 AND BINARY b.`requestitemstext`=BINARY 'Is your task complete, $n? Do you have the Burning Blade Medallion?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25135,'Отлично, нашлась! Огромное спасибо, $n. Это моя любимая кирка! Если мои батраки когда-нибудь закончат рубить эти деревья, может, найдём хорошую пещеру для добычи!' FROM `quest_template` b WHERE b.`id`=25135 AND BINARY b.`offerrewardtext`=BINARY 'Great, you got it! Thanks a lot, $n. This is my favorite pick! Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25166,'Моё терпение на исходе. У меня нет времени ждать, так что убей уже того капитана.$B$BЭ-э, то есть... пожалуйста? Хи-хи?' FROM `quest_template` b WHERE b.`id`=25166 AND BINARY b.`requestitemstext`=BINARY 'My patience is beginning to wear thin. I don\'t have enough time to wait around for you, so kill that captain already.$B$BUm, I mean, please? Tee-hee?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25167,'Пока мы им помешали, но они всё ещё здесь. Придётся продолжать, $n.' FROM `quest_template` b WHERE b.`id`=25167 AND BINARY b.`offerrewardtext`=BINARY 'Well, we\'ve stymied their efforts for now, but they\'re still here.  We\'ll have to press on, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25167,'Надо избавиться от этих людей, $c.' FROM `quest_template` b WHERE b.`id`=25167 AND BINARY b.`requestitemstext`=BINARY 'We gotta get rid of these humans, $c.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25168,'Убей их всех.' FROM `quest_template` b WHERE b.`id`=25168 AND BINARY b.`requestitemstext`=BINARY 'Slay them all.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25169,'Уничтожь этих людей, $n.' FROM `quest_template` b WHERE b.`id`=25169 AND BINARY b.`requestitemstext`=BINARY 'Destroy those humans, $n.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25172,'Скорее, $n. Расправься с этими людьми в нашей долине.' FROM `quest_template` b WHERE b.`id`=25172 AND BINARY b.`requestitemstext`=BINARY 'Quickly, $n. Dispatch of these humans in our valley.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25177,'От тебя пахнет морем, $N. Благодаря тебе у Колючего Холма, возможно, есть ещё день.$b$bЯ сообщу о твоих деяниях вышестоящим командирам. Мы тебе благодарны.' FROM `quest_template` b WHERE b.`id`=25177 AND BINARY b.`offerrewardtext`=BINARY 'The scent of the sea hangs about you, $N.  Your efforts may have purchased another day for Razor Hill.$b$bI will pass word of your deeds up my chain of command.  You have our gratitude.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25232,'Это весьма интересно. Эти обряды не так уж отличаются от заклинаний, которым обучают чернокнижников Орды. Нужно изучить это подробнее!' FROM `quest_template` b WHERE b.`id`=25232 AND BINARY b.`offerrewardtext`=BINARY 'This is quite interesting.  These rites aren\'t all that different from the spells which are taught to Horde warlocks.  This merits further investigation!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25232,'Свитки, $N, свитки!' FROM `quest_template` b WHERE b.`id`=25232 AND BINARY b.`requestitemstext`=BINARY 'The scrolls, $N, the scrolls!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25258,'Теперь я в растерянности, $N... Ты легко одолеваешь его в бою, но, с другой стороны, он достался мне даром и прокормить его недорого. Пожалуй, пока оставим его при себе.' FROM `quest_template` b WHERE b.`id`=25258 AND BINARY b.`offerrewardtext`=BINARY 'I\'m at a crossroads now, $N... you defeated him easily in combat, but then again, I did get him for free, and he\'s pretty cheap to feed.  Maybe we\'ll keep him around for a bit.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25284,'Расскажи мне о стражниках. Хаос? Страх? Паника? А?' FROM `quest_template` b WHERE b.`id`=25284 AND BINARY b.`requestitemstext`=BINARY 'Tell me about the guards. Chaos? Fear? Panic? Hm?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25364,'Моя просьба выполнена, и за это я отдаю тебе честь. Прими эту скромную награду за свои труды, $n.$B$BТеперь, когда гноллов стало меньше, а их предводители убиты, они дважды подумают, прежде чем штурмовать лагерь. Но этим дело не заканчивается...$B$BДолжно быть, что-то привело их в такое неистовство. Пока они не успели собраться с силами, я хочу выяснить причину.' FROM `quest_template` b WHERE b.`id`=25364 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, $n.$B$BWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn\'t conclude the issue at hand, however...$B$BThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup, I want to find out what is causing it.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25367,'Как идёт охота, $N? Пришло время сообщить об успехах?' FROM `quest_template` b WHERE b.`id`=25367 AND BINARY b.`requestitemstext`=BINARY 'How goes the hunt, $N?  Are you here to report your success?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25369,'Впечатляет, $c... весьма впечатляет! Если Жалохвост действительно одно из сильнейших их созданий, со временем изучение этого зверя принесёт немалую пользу. Теперь моя задача — продержаться достаточно долго, чтобы мы успели ею воспользоваться.$B$BПрими эту денежную награду в знак благодарности всего лагеря, $N. Молодец.' FROM `quest_template` b WHERE b.`id`=25369 AND BINARY b.`offerrewardtext`=BINARY 'Impressive, $c... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It\'s now my charge to make sure we defend ourselves long enough to take advantage of it.$B$BPlease accept this coin bounty as a token of the entire camp\'s thanks, $N.  Well done.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25369,'Ну что, удалось тебе одолеть жалохвоста?' FROM `quest_template` b WHERE b.`id`=25369 AND BINARY b.`requestitemstext`=BINARY 'Have you managed to bring down Stinglasher yet?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25374,'Теперь я могу спать спокойно, $n. Благодаря тебе наш лагерь избавлен от страшной угрозы.' FROM `quest_template` b WHERE b.`id`=25374 AND BINARY b.`offerrewardtext`=BINARY 'I will be able to rest easy now, $n. You\'ve saved our camp from a terrible menace.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25397,'Со временем духи этих хранителей вернутся, $n. Благодаря тебе они свободны и могут продолжить свой путь в круговороте природы.$B$BТеперь мы должны позаботиться о том, чтобы в нём не было ни скверны, ни напрасных страданий.' FROM `quest_template` b WHERE b.`id`=25397 AND BINARY b.`offerrewardtext`=BINARY 'The spirits of these guardians will return in time, $n. You\'ve freed them to move on in nature\'s cycle.$B$BNow it falls to us to make sure that cycle is free of corruption and needless suffering.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25419,'Вы осматриваете цепь в надежде, что её можно восстановить.' FROM `quest_template` b WHERE b.`id`=25419 AND BINARY b.`requestitemstext`=BINARY 'You examine the chain, hoping it can be restored.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25421,'Поразительно. Эти иероглифы, несомненно, принадлежат титанам, но знаки под ними...$B$BХочется верить, что это один и тот же отрывок, записанный на множестве древних языков. Возможно, с его помощью мы расшифруем иероглифы! Если, как ты говоришь, ими покрыта вся передняя камера, кто знает, что ещё мы узнаем.$B$BЯ хочу вручить тебе достойную награду, $N. Это находка века!' FROM `quest_template` b WHERE b.`id`=25421 AND BINARY b.`offerrewardtext`=BINARY 'This is amazing. These hieroglyphs are undoubtedly titan, but the markings below it...$B$BIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs! If the antechamber was covered in them as you say, who knows what else we\'ll learn.$B$BI\'d like to grant you a fine reward, $N. We\'ve made the find of the century!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25421,'Вот и ты! Что удалось найти?' FROM `quest_template` b WHERE b.`id`=25421 AND BINARY b.`requestitemstext`=BINARY 'You\'re back! What have you found?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25426,'Отличная работа, $n. Я и не думал, что эти гноллы доставят тебе много хлопот.' FROM `quest_template` b WHERE b.`id`=25426 AND BINARY b.`offerrewardtext`=BINARY 'Excellent work, $n. I didn\'t think those gnolls would give you much trouble.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25426,'Гривы нужны не только как трофеи. Раз уж приходится убивать, пусть хоть что-нибудь не пропадёт зря.' FROM `quest_template` b WHERE b.`id`=25426 AND BINARY b.`requestitemstext`=BINARY 'The manes aren\'t just for trophies. If there\'s to be slaughter, we may as well not let it be a total waste.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25429,'Как идёт охота, $N? Пришло время сообщить об успехах?' FROM `quest_template` b WHERE b.`id`=25429 AND BINARY b.`requestitemstext`=BINARY 'How goes the hunt, $N?  Are you here to report your success?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25432,'Приятно снова тебя видеть. Мы узнали кое-что ещё о том, что происходит с ограми.' FROM `quest_template` b WHERE b.`id`=25432 AND BINARY b.`offerrewardtext`=BINARY 'It\'s good to see you back. We\'ve learned more about the ogre situation.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25433,'Снова отличная работа, $n. Фералас избавлен ещё от одной угрозы.' FROM `quest_template` b WHERE b.`id`=25433 AND BINARY b.`offerrewardtext`=BINARY 'Well done once again, $n. Yet another threat removed from Feralas.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25434,'Отличная работа, и скатертью им дорога. Надеюсь, больше ни одного огра здесь не увижу!' FROM `quest_template` b WHERE b.`id`=25434 AND BINARY b.`offerrewardtext`=BINARY 'Good work, and good riddance. I hope we never have to see another ogre here again!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25437,'Вот и ты.$B$BМне стыдно просить тебя об этом, $c, но я уже слишком долго бегу от него. Таэрара нужно остановить.' FROM `quest_template` b WHERE b.`id`=25437 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve come.$B$BI am ashamed to ask this of you, $c, but I\'ve ran from him long enough. Taerar must be stopped.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25447,'По крайней мере, страдания этих существ закончились. Будем надеяться, что их жертва избавит других от боли.' FROM `quest_template` b WHERE b.`id`=25447 AND BINARY b.`offerrewardtext`=BINARY 'At the very least, these creatures\' suffering has ended. Let us hope their sacrifice will bring a stop to further pain.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25447,'Печальная задача, $n, но необходимая.' FROM `quest_template` b WHERE b.`id`=25447 AND BINARY b.`requestitemstext`=BINARY 'This is a sad task, $n, but necessary.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25450,'Отлично, отлично! Они прекрасно подойдут: уже видно, что после правильной обработки они станут намного прочнее.$B$BЕщё раз спасибо за помощь, $N. Вот, прошу, возьми одно из моих последних творений.' FROM `quest_template` b WHERE b.`id`=25450 AND BINARY b.`offerrewardtext`=BINARY 'Excellent, excellent!  These are going to work out incredibly well - I can already tell that they\'re going to be much harder when properly cured.$B$BThanks again for your help $N.  Here - please take one of my latest creations.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25477,'Удалось приручить морскую черепаху, $n?' FROM `quest_template` b WHERE b.`id`=25477 AND BINARY b.`requestitemstext`=BINARY 'Were you able to tame a sea turtle, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25481,'Тебя прислал Хранитель дорог Фалфиндел? Хорошо! Нам нужна твоя помощь, немедленно!' FROM `quest_template` b WHERE b.`id`=25481 AND BINARY b.`offerrewardtext`=BINARY 'Falfindel Waywarder sent you? Good! We need your help, now!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25517,'Что? Не слышишь?$B$BНужно пойти и устроить драку в таверне... сейчас же!' FROM `quest_template` b WHERE b.`id`=25517 AND BINARY b.`requestitemstext`=BINARY 'What? Are you deaf?$B$BYou need to go start that bar fight... now!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25552,'Вот и ты, $r.' FROM `quest_template` b WHERE b.`id`=25552 AND BINARY b.`requestitemstext`=BINARY 'You\'ve returned, $r.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25588,'Вот этим паршивым псам и урок! Благодарю тебя, $N.' FROM `quest_template` b WHERE b.`id`=25588 AND BINARY b.`offerrewardtext`=BINARY 'That\'ll teach those scurvy dogs! You have my thanks, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25607,'А, вот и хлам! Это последняя часть головоломки! Теперь всё установим! Приготовься, $N!' FROM `quest_template` b WHERE b.`id`=25607 AND BINARY b.`offerrewardtext`=BINARY 'Ah, ze junk haz arrived! Zit is ze last piece of ze puzzle! Now to zet it up! Standby, $N!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25607,'Хлам? Он у тебя?' FROM `quest_template` b WHERE b.`id`=25607 AND BINARY b.`requestitemstext`=BINARY 'Ze junk? Do you have zit?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25622,'<ГНМ-передатчик громко гудит.>$B$BВеликолепно! Как и обещано, ВУАЛЯ — твоя награда!$B$BА теперь у меня есть новости, которые могут тебя заинтересовать.' FROM `quest_template` b WHERE b.`id`=25622 AND BINARY b.`offerrewardtext`=BINARY '<The Gnomecorder buzzes loudly.>$B$BVonderful! As promised, VOILA, your reward!$B$BNow, I have a bit of news that you might find interesting.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25659,'Твой враг совсем недалеко, нужно лишь немного проплыть по этому залу. Ступай и неси с собой смерть.' FROM `quest_template` b WHERE b.`id`=25659 AND BINARY b.`requestitemstext`=BINARY 'Your foe is but a short swim down this hall. Go, and bring death with you.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25662,'Ключ от этой клетки у моего тюремщика.' FROM `quest_template` b WHERE b.`id`=25662 AND BINARY b.`requestitemstext`=BINARY 'My captor holds the key to this cage.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25705,'Да направит тебя Нептулон, обитатель суши.' FROM `quest_template` b WHERE b.`id`=25705 AND BINARY b.`requestitemstext`=BINARY 'Neptulon guide you, landwalker.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25722,'Что ж. Хорошая новость: эти образцы отлично подойдут. Плохая: даже спьяну я вижу, что для здешнего верхнего слоя почвы у них не тот цвет.$B$BЗначит, дела в этих краях плохи, $n. Но прежде чем сдаваться, проведём ещё испытания.' FROM `quest_template` b WHERE b.`id`=25722 AND BINARY b.`offerrewardtext`=BINARY 'Ah, well. The good news is, these will do perfectly. The bad news is I can tell they\'re the wrong color for topsoil here, even drunk as I am.$B$BThat means things aren\'t looking good for the area, $n. But we\'ve got more tests to run before we hang up the towel.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25722,'Ну что ж, давай посмотрим на осадок.' FROM `quest_template` b WHERE b.`id`=25722 AND BINARY b.`requestitemstext`=BINARY 'Let\'s see the sediment, then.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25736,'А в этой штуке ещё хватает бойцовского духа! Поразительно!$B$BТы крепкий орешек, $n. Мы очень ценим твою помощь. Думаю, перед уходом тебе полагается награда.$B$BИ впредь старайся ради Стальгорна, слышишь? А если встретишь мою сестру, передай от меня привет.' FROM `quest_template` b WHERE b.`id`=25736 AND BINARY b.`offerrewardtext`=BINARY 'The thing\'s still got some fight in it! Amazing!$B$BYou\'re a tough one, $n. It\'s much appreciated. I\'d say a reward is in order before you head out.$B$BKeep doin\' your best for Ironforge, you hear? And if you ever see my sister, say hello for me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25736,'А? Что это у тебя?' FROM `quest_template` b WHERE b.`id`=25736 AND BINARY b.`requestitemstext`=BINARY 'Eh? What\'s that you\'ve got there?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25741,'Теперь запаса противоядия нам хватит надолго. Спасибо, $N!' FROM `quest_template` b WHERE b.`id`=25741 AND BINARY b.`offerrewardtext`=BINARY 'This will keep us stocked on anti-venom for the foreseeable future. Thank you, $N!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25741,'Ядовитые железы, которые я просил, у тебя?' FROM `quest_template` b WHERE b.`id`=25741 AND BINARY b.`requestitemstext`=BINARY 'Have you recovered the venom sacs I requested?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25778,'Просто положи это на землю, $R.' FROM `quest_template` b WHERE b.`id`=25778 AND BINARY b.`offerrewardtext`=BINARY 'Just put it down on the ground, $R.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25778,'Что это? Да у тебя немало золота.' FROM `quest_template` b WHERE b.`id`=25778 AND BINARY b.`requestitemstext`=BINARY 'What\'s this? That is a lot of gold you have there.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25800,'Сытный обед из морепродуктов всем поднимет настроение и поможет нам снова привести город в порядок. Спасибо за помощь, $n.' FROM `quest_template` b WHERE b.`id`=25800 AND BINARY b.`offerrewardtext`=BINARY 'A hearty seafood dinner will lift everyone\'s spirits and help us get the town back in shape again. Thanks for the help, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25800,'С мелкими клешнями не возись: мяса в них меньше, чем мороки.' FROM `quest_template` b WHERE b.`id`=25800 AND BINARY b.`requestitemstext`=BINARY 'Don\'t bother with the smaller claws, they\'re more work to shell than the meat\'s worth.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25801,'Наши торговцы не будут в безопасности, пока мы не избавимся от Жруна и этих мурлоков.' FROM `quest_template` b WHERE b.`id`=25801 AND BINARY b.`requestitemstext`=BINARY 'Our merchants will not be safe until we are rid of Gobbler and those murlocs.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25806,'<ГНМ-передатчик жужжит и гудит.>$B$BЭй, эта штука работает?$B$B<Вы слышите постукивание.>$B$BЕсть там кто-нибудь?' FROM `quest_template` b WHERE b.`id`=25806 AND BINARY b.`offerrewardtext`=BINARY '<The Gnomecorder buzzes and whirs.>$B$BHey, this thing on?$B$B<You hear a tapping sound.>$B$BAnybody there?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25808,'Отлично, $N! С минами ты обращаешься как настоящий мастер. А теперь верни мои очки.' FROM `quest_template` b WHERE b.`id`=25808 AND BINARY b.`offerrewardtext`=BINARY 'Nicely done, $N! You worked the mines like a pro. Now how about returning my goggles.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25808,'А, значит, ты ещё живёшь.' FROM `quest_template` b WHERE b.`id`=25808 AND BINARY b.`requestitemstext`=BINARY 'Oh so you are alive.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25821,'Я с первого взгляда понял, что ты не чета остальным, $N. Настолько, что никому другому здесь я не доверил бы то, о чём собираюсь тебя попросить.' FROM `quest_template` b WHERE b.`id`=25821 AND BINARY b.`offerrewardtext`=BINARY 'I knew that you\'d be a special snowflake when I first set my eyes upon you, $N. So special, in fact, that I\'d trust no one else here with what I\'m about to ask of you.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25823,'Я вызову пехоту, чтобы она выдвинулась и разобралась с тем, что осталось. Вот бы нам ещё десять тысяч таких, как ты, $N!' FROM `quest_template` b WHERE b.`id`=25823 AND BINARY b.`offerrewardtext`=BINARY 'I will call for the infantry to move in and clear up whatever might be left over. If only we had ten-thousand more like you, $N!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25825,'Это масло! Ты и впрямь становишься незаменимым помощником, $N!$B$BЖаль, что теперь мне придётся тебя отослать.' FROM `quest_template` b WHERE b.`id`=25825 AND BINARY b.`offerrewardtext`=BINARY 'It is oil! You\'re really proving yourself to be invaluable, $N!$B$BToo bad I\'m going to have to send you off now.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25825,'Что это? Неужели масло?!' FROM `quest_template` b WHERE b.`id`=25825 AND BINARY b.`requestitemstext`=BINARY 'What\'s this? Is that oil?!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25837,'Отойди, $N, сейчас будет настоящий взрыв вкуса, и я не хочу, чтобы тебя задело.' FROM `quest_template` b WHERE b.`id`=25837 AND BINARY b.`offerrewardtext`=BINARY 'Stand back, $N, there\'s about to be a flavor explosion and I wouldn\'t want ya gettin\' hurt.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25845,'Ну???' FROM `quest_template` b WHERE b.`id`=25845 AND BINARY b.`requestitemstext`=BINARY 'Well???' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25846,'Оружие у тебя?' FROM `quest_template` b WHERE b.`id`=25846 AND BINARY b.`requestitemstext`=BINARY 'Do you have the weapons?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25849,'Да не стесняйся! Тащи целую охапку!' FROM `quest_template` b WHERE b.`id`=25849 AND BINARY b.`requestitemstext`=BINARY 'Don\'t be coy about it, now! Bring back a good armful of \'em!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25856,'Крокодильи шкуры для меня есть?' FROM `quest_template` b WHERE b.`id`=25856 AND BINARY b.`requestitemstext`=BINARY 'Got any croc hides for me?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25873,'Что это, $C?' FROM `quest_template` b WHERE b.`id`=25873 AND BINARY b.`requestitemstext`=BINARY 'What\'s this, $C?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25889,'Хвала тебе, $N. Наконец-то появился герой, которого мы искали, и как раз вовремя.' FROM `quest_template` b WHERE b.`id`=25889 AND BINARY b.`offerrewardtext`=BINARY 'Praise you, $N. The hero we have been searching for has finally arrived, and not a moment too soon.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25889,'Призови моего гиппогрифа свистком, $N.' FROM `quest_template` b WHERE b.`id`=25889 AND BINARY b.`requestitemstext`=BINARY 'Use the whistle to call for my hippogryph, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25913,'Спасибо, $N. На клинке каждой глефы выгравировано имя стража, которому она принадлежала. Теперь мы можем известить семьи погибших и дать их душам упокоиться.' FROM `quest_template` b WHERE b.`id`=25913 AND BINARY b.`offerrewardtext`=BINARY 'Thank you, $N. Each glaive has the name of the sentinel it belonged to imprinted upon its blade. We can now send word to their families and put their souls to rest.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25930,'<ГНМ-передатчик потрескивает от энергии.>$B$BЭй, ты там, $N? Похоже, ты в самом сердце драконьего логова.' FROM `quest_template` b WHERE b.`id`=25930 AND BINARY b.`offerrewardtext`=BINARY '<The Gnomecorder crackles with energy.>$B$BI say, are you there, $N? It would appear that you are in the center of a dragon\'s lair.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 25935,'Прекрасно. Собаки будут сыты и смогут защищать нашу заставу ещё несколько недель!' FROM `quest_template` b WHERE b.`id`=25935 AND BINARY b.`offerrewardtext`=BINARY 'Excellent. The dogs will be well fed and ready to defend our outpost for weeks!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25935,'Поторопись, $N, щенки голодные!' FROM `quest_template` b WHERE b.`id`=25935 AND BINARY b.`requestitemstext`=BINARY 'Hurry, $N, the pups are hungry!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 25964,'Дела у этих ребят плохи. Возможно, придётся отступить раньше, чем хотелось бы.' FROM `quest_template` b WHERE b.`id`=25964 AND BINARY b.`requestitemstext`=BINARY 'These guys aren\'t in good shape. We may need to retreat sooner than we\'d like.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26024,'Приветствую, $c. Есть что доложить?' FROM `quest_template` b WHERE b.`id`=26024 AND BINARY b.`requestitemstext`=BINARY 'Greetings, $c.  You have a report to make?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26078,'Нужно скорее поднять эти бомбардировщики в воздух!' FROM `quest_template` b WHERE b.`id`=26078 AND BINARY b.`requestitemstext`=BINARY 'We need to hurry and get those bombers airborne!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26079,'Здравствуй. Есть что доложить?' FROM `quest_template` b WHERE b.`id`=26079 AND BINARY b.`requestitemstext`=BINARY 'Hello.  Do you have a report to submit?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26107,'В глазах наших воинов будет та же свирепость, что и в глазах ящеров.' FROM `quest_template` b WHERE b.`id`=26107 AND BINARY b.`requestitemstext`=BINARY 'The fierceness in the eyes of the raptors will be matched by those of our warriors.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26149,'Отличная работа. Теперь можно не тревожиться о том, что случилось бы с ними без тебя.$B$BПоследний даже отблагодарил тебя наградой, которую всё это время прятал при себе.' FROM `quest_template` b WHERE b.`id`=26149 AND BINARY b.`offerrewardtext`=BINARY 'A job well done. Now you don\'t need to worry about what would have happened to them if you hadn\'t been around.$B$BThe last one was even appreciative enough to give you a reward they\'d kept hidden on their person.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26154,'ИХ МОЛИТВЫ... СМОЛКЛИ.$B$BТЕПЕРЬ... ИХ СИЛА... У ТЕБЯ... ТЫ ДОЛЖЕН УНИЧТОЖИТЬ... ИХ ПРЕДВОДИТЕЛЯ.' FROM `quest_template` b WHERE b.`id`=26154 AND BINARY b.`offerrewardtext`=BINARY 'THEIR DEVOTIONS ARE... SILENCED.$B$BNOW THAT... YOU HAVE... THEIR POWER... YOU MUST DESTROY... THEIR LEADER.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26160,'Ритуал ещё не завершён.' FROM `quest_template` b WHERE b.`id`=26160 AND BINARY b.`requestitemstext`=BINARY 'The ritual is not yet complete.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26180,'Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая Компания во имя прибыли.' FROM `quest_template` b WHERE b.`id`=26180 AND BINARY b.`requestitemstext`=BINARY 'I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26244,'Вот и ты, $N.' FROM `quest_template` b WHERE b.`id`=26244 AND BINARY b.`requestitemstext`=BINARY 'You\'ve returned, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26273,'Сила — не главное в победе над врагом и уж точно не главное, если хочешь выжить. В бою важен баланс. Всему своё время и место.' FROM `quest_template` b WHERE b.`id`=26273 AND BINARY b.`requestitemstext`=BINARY 'Strength isn\'t da end all of defeating ya enemy, and it most certainly isn\'t tha end all of stayin\' alive. Fightin\' is about balance. Everytin has its time and place.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26275,'Вряд ли с ними будет трудно, дружище, но если не будешь проворно двигаться, они тебе все лодыжки исцарапают.' FROM `quest_template` b WHERE b.`id`=26275 AND BINARY b.`requestitemstext`=BINARY 'I doubt dey too much of a challenge, mon, but they\'ll still claw up ya ankles if ya don\'t stay quick footed.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26276,'А ты неплохо справляешься. Когда-нибудь тебе не будет равных.' FROM `quest_template` b WHERE b.`id`=26276 AND BINARY b.`offerrewardtext`=BINARY 'Ya handle yerself quite well. Ya gonna be quite powerful some day.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26329,'Приятно снова видеть тебя, $n.' FROM `quest_template` b WHERE b.`id`=26329 AND BINARY b.`requestitemstext`=BINARY 'Welcome back, $n.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26347,'Без слизи пламя долго не продержится, $N. Раньше мы использовали масло, но его было трудно достать!' FROM `quest_template` b WHERE b.`id`=26347 AND BINARY b.`requestitemstext`=BINARY 'The flame will not burn for long without ooze, $N. We used to use oil back in the day, but it was hard to come by!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26349,'Удалось покончить с угрозой по имени Старый Мрачноглаз? Его замечали на побережье Западного Края.$b$bВозвращайся ко мне, когда эта мерзкая тварь будет мертва.' FROM `quest_template` b WHERE b.`id`=26349 AND BINARY b.`requestitemstext`=BINARY 'Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.$b$bReturn to me when the foul beast is dead.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26382,'Надеюсь, этого хватит.' FROM `quest_template` b WHERE b.`id`=26382 AND BINARY b.`requestitemstext`=BINARY 'I hope you brought enough.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26394,'А, записка от Кузнеца Аргуса? Не удивлён, что ему нужно ещё снаряжение. Новобранцев нынче так много.$B$BЧто ж, спасибо, $N. Вот немного денег на дорожные расходы.' FROM `quest_template` b WHERE b.`id`=26394 AND BINARY b.`offerrewardtext`=BINARY 'Ah, a note from Smith Argus?  I\'m not surprised he needs more gear.  There are so many new recruits these days.$B$BWell thank you, $N.  Here\'s some money to cover your travel costs.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26434,'Выбирай реагенты помягче, $n. Колючие совсем не годятся.' FROM `quest_template` b WHERE b.`id`=26434 AND BINARY b.`requestitemstext`=BINARY 'Make sure the reagents are extra-cushy, $n.  A scratchy reagent simply won\'t do.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26435,'Да, $r? Я довольно занят' FROM `quest_template` b WHERE b.`id`=26435 AND BINARY b.`requestitemstext`=BINARY 'Yes, $r? I\'m quite busy' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26446,'Неужели все мои семена уже посажены?' FROM `quest_template` b WHERE b.`id`=26446 AND BINARY b.`requestitemstext`=BINARY 'Surely you have not yet planted all of my seeds?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26450,'Покажи-ка!' FROM `quest_template` b WHERE b.`id`=26450 AND BINARY b.`requestitemstext`=BINARY 'Let\'s see \'em!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26455,'Отличная работа, $N. Здесь определённо таится сила, которую не смогло ослабить даже постоянное воздействие скверны сатиров.$B$BВидишь, как оно всё ещё сияет спустя столько лет?' FROM `quest_template` b WHERE b.`id`=26455 AND BINARY b.`offerrewardtext`=BINARY 'Excellent work, $N. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim.$B$BDo you see how it still shines, after all these years?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26456,'Что это у тебя, $c?' FROM `quest_template` b WHERE b.`id`=26456 AND BINARY b.`requestitemstext`=BINARY 'What\'s that you have there, $c?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26495,'Не хочешь объясниться, $c?' FROM `quest_template` b WHERE b.`id`=26495 AND BINARY b.`requestitemstext`=BINARY 'Care to explain yourself, $c?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26514,'Ошейники найдены?' FROM `quest_template` b WHERE b.`id`=26514 AND BINARY b.`requestitemstext`=BINARY 'Did you recover those collars?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26544,'Что удалось узнать?' FROM `quest_template` b WHERE b.`id`=26544 AND BINARY b.`requestitemstext`=BINARY 'What have you found out?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26570,'Благодаря тебе у нас, пожалуй, есть ещё день, а то и два. Отличная работа, $n.' FROM `quest_template` b WHERE b.`id`=26570 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve probably bought us another day, maybe two. Nice work, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26599,'Йо-хо-хо, $N! Удалось найти Горлаша? Это был мой любимый сундук, а в потайном отделении хранились мои величайшие сокровища!' FROM `quest_template` b WHERE b.`id`=26599 AND BINARY b.`requestitemstext`=BINARY 'Ahoy, $N!  Did you find Gorlash?  That chest was my favorite, and it has a hidden compartment that held my greatest treasures!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26600,'Это ведь недорого стоило? Ну, вот тебе немного монет в возмещение.$b$bА теперь займёмся местью, а?' FROM `quest_template` b WHERE b.`id`=26600 AND BINARY b.`offerrewardtext`=BINARY 'This wasn\'t expensive, was it?  Well, here\'s some pieces of eight to reimburse you.$b$bNow let\'s get onto this revenge, shall we?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26600,'Нам понадобится много еды, $n. Здесь количество важнее качества.' FROM `quest_template` b WHERE b.`id`=26600 AND BINARY b.`requestitemstext`=BINARY 'We\'re going to need a lot of food, $n.  Quantity over quality is the goal here.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26613,'Отлично, $n! И как раз перед отплытием! Даже не знаю, как тебя отблагодарить, дружище.' FROM `quest_template` b WHERE b.`id`=26613 AND BINARY b.`offerrewardtext`=BINARY 'Good show, $n!  And just before I need to ship out too!  Can\'t thank you enough, old friend.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26613,'Ну что, дружище, удалось найти товары?' FROM `quest_template` b WHERE b.`id`=26613 AND BINARY b.`requestitemstext`=BINARY 'Any luck finding the goods, matey?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26635,'Знаешь, я не всегда драил палубу.' FROM `quest_template` b WHERE b.`id`=26635 AND BINARY b.`requestitemstext`=BINARY 'I wasn\'t always a swabbie, you know.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26645,'Прекрасно, $n. За службу жителям Темнолесья ты получишь награду.' FROM `quest_template` b WHERE b.`id`=26645 AND BINARY b.`offerrewardtext`=BINARY 'Splendid, $n. For your service to the people of Darkshire you shall be rewarded.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26685,'Тебе удалось уговорить Ззарк\'Вула одолжить нам свой монокль для эксперимента?' FROM `quest_template` b WHERE b.`id`=26685 AND BINARY b.`requestitemstext`=BINARY 'Were you able to convince Zzarc\'Vul to lend us his monocle for our experiment?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26688,'Впечатляет, $n. Похоже, ты умеешь постоять за себя. Возможно, для твоих способностей найдётся более подходящее испытание.' FROM `quest_template` b WHERE b.`id`=26688 AND BINARY b.`offerrewardtext`=BINARY 'Impressive, $n. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26691,'Да, что такое? Побыстрее, у меня срочные дела.' FROM `quest_template` b WHERE b.`id`=26691 AND BINARY b.`requestitemstext`=BINARY 'Yes, what is it? Make it quick, I\'ve pressing matters to attend to.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26729,'Да, $n?' FROM `quest_template` b WHERE b.`id`=26729 AND BINARY b.`requestitemstext`=BINARY 'Yes, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26731,'С нетерпением жду результатов.' FROM `quest_template` b WHERE b.`id`=26731 AND BINARY b.`requestitemstext`=BINARY 'I eagerly await the results.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26733,'С этим эликсиром что-то не так, $N. Я ещё не закончил анализ, но уже чувствую.' FROM `quest_template` b WHERE b.`id`=26733 AND BINARY b.`requestitemstext`=BINARY 'There\'s something not quite healthy about this elixir, $N.  Even though I haven\'t completed my analysis, I can sense it.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26734,'Обращайся с этим осторожно, $N. Мы ведь не знаем, что это такое.' FROM `quest_template` b WHERE b.`id`=26734 AND BINARY b.`requestitemstext`=BINARY 'Make sure you handle that stuff carefully, $N.  We don\'t know what it is.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26735,'Что удалось найти, $n?' FROM `quest_template` b WHERE b.`id`=26735 AND BINARY b.`requestitemstext`=BINARY 'What were you able to find, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26743,'Похоже, эти тотемные создания изображают каких-то удивительных существ, обитающих в джунглях.' FROM `quest_template` b WHERE b.`id`=26743 AND BINARY b.`requestitemstext`=BINARY 'It\'s likely that these totemic creatures are based on some of the fantastic creatures that roam this jungle.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26747,'Ган\'зулах был грубияном и тираном. Чувствую, этот тролль будет другим. Тролльская магия оказалась проще, чем я думал!' FROM `quest_template` b WHERE b.`id`=26747 AND BINARY b.`requestitemstext`=BINARY 'Gan\'zulah was a brute and a tyrant.  I\'ve got a feeling that this troll will be different.  This troll magic is easier than I thought it would be!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26748,'Мне нужен только ящер, $r. Отдай его мне, и гном останется жив.' FROM `quest_template` b WHERE b.`id`=26748 AND BINARY b.`requestitemstext`=BINARY 'All I ask is the raptor, $r.  Give it to me, and the gnome lives.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26760,'Погоди, мы ещё не закончили.' FROM `quest_template` b WHERE b.`id`=26760 AND BINARY b.`requestitemstext`=BINARY 'Excuse me, we\'re not done yet.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26765,'Здравствуй, $N. Гоблин Кразек починил мой котёл??' FROM `quest_template` b WHERE b.`id`=26765 AND BINARY b.`requestitemstext`=BINARY 'Hello, $N.  Did the goblin Krazek fix my pot??' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26772,'Ящер по имени Оган\'ака всё ещё твой друг.' FROM `quest_template` b WHERE b.`id`=26772 AND BINARY b.`requestitemstext`=BINARY 'Raptor named Ohgan\'aka, still your friend.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26774,'Для особо мощных заклинаний нужен особо большой ум, да.' FROM `quest_template` b WHERE b.`id`=26774 AND BINARY b.`requestitemstext`=BINARY 'Extra-big spells need extra-big brains, yes.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26799,'В новой жизни ты далеко не уйдёшь, если не можешь убить даже самых слабых и безмозглых созданий, $N. Не возвращайся без добрых вестей.' FROM `quest_template` b WHERE b.`id`=26799 AND BINARY b.`requestitemstext`=BINARY 'You will not go far in this new life if you are unable to kill even the weakest, most brainless creatures, $N.  Do not return until you have success to report.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26801,'Кто медлит с этим заданием, может в итоге так же бесцельно бродить, как наши павшие братья и сёстры в деревне. Будем надеяться, твоя судьба окажется лучше, да?' FROM `quest_template` b WHERE b.`id`=26801 AND BINARY b.`requestitemstext`=BINARY 'Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let\'s hope you will fare better than them, yes? ' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26875,'Нельзя допустить, чтобы связывание прервали. В дальних комнатах нужна твоя помощь — поторопись.' FROM `quest_template` b WHERE b.`id`=26875 AND BINARY b.`requestitemstext`=BINARY 'We cannot let the binding be interrupted. They need your help in the back rooms - please hurry.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26876,'$N! Вот и ты!' FROM `quest_template` b WHERE b.`id`=26876 AND BINARY b.`requestitemstext`=BINARY '$N!  You\'ve returned!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26932,'Это должно уберечь оставшуюся у нас воду от распространения болезней и заразы. Большое спасибо, $n.' FROM `quest_template` b WHERE b.`id`=26932 AND BINARY b.`offerrewardtext`=BINARY 'That should help prevent disease and illness from spreading into our remaining water. Many thanks, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26934,'В тканях животных болезнь сохраняется куда лучше, чем в тканях растений, не так ли?' FROM `quest_template` b WHERE b.`id`=26934 AND BINARY b.`requestitemstext`=BINARY 'Animal tissue holds onto disease so much better than plant tissue, doesn\'t it?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26961,'Идолы у тебя? Мы должны изучить их и сообщить о находках в Стальгорн!' FROM `quest_template` b WHERE b.`id`=26961 AND BINARY b.`requestitemstext`=BINARY 'Do you have those idols?  We must study them and report our findings to Ironforge!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26993,'Отлично. Как насчёт хорошей награды за твою работу в обмен на молчание о нашей встрече? По рукам?' FROM `quest_template` b WHERE b.`id`=26993 AND BINARY b.`offerrewardtext`=BINARY 'Well done. How about I give you a nice reward for your work, and you don\'t tell a soul that you saw me here. Deal?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26993,'Не хочу надолго задерживаться в монастыре, полном фанатиков, ненавидящих нежить. Думаю, ты понимаешь почему. Не заговаривай со мной, если у тебя нет книги.' FROM `quest_template` b WHERE b.`id`=26993 AND BINARY b.`requestitemstext`=BINARY 'I don\'t want to stay in a monastery packed full of undead-hating zealots for much longer. Surely you can understand why. Don\'t speak to me if you don\'t have the book with you.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26994,'Очень хорошо. Да, просто прекрасно.$B$BВот твоя награда, как и обещано. Без лишних вопросов.' FROM `quest_template` b WHERE b.`id`=26994 AND BINARY b.`offerrewardtext`=BINARY 'Very good. Yes, very good indeed.$B$BYour reward, as promised. No questions.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 26996,'<Доминик вручает вам награду, не произнося ни слова.>' FROM `quest_template` b WHERE b.`id`=26996 AND BINARY b.`offerrewardtext`=BINARY '<Dominic hands you your reward. No words are spoken.>' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 26996,'<Доминик пристально смотрит на вас.>' FROM `quest_template` b WHERE b.`id`=26996 AND BINARY b.`requestitemstext`=BINARY '<Dominic stares at you.>' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27016,'Уже десять убито? Х... ха! А я за это время побил свой прежний рекорд! До десяти... сотен! Да, десять сотен кабанов!$B$BУговор есть уговор... вот твой утешительный приз, $n!' FROM `quest_template` b WHERE b.`id`=27016 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve killed ten already? H...hah! While you were out, I\'ve broken my previous record! To ten... hundred! Yes, ten hundred boars!$B$BA bet is a bet, I suppose... here\'s your consolation prize, $n!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27037,'Отличная работа, $n! Вот уж мы ему показали! Давай голову, я о ней позабочусь.' FROM `quest_template` b WHERE b.`id`=27037 AND BINARY b.`requestitemstext`=BINARY 'Great job, $n! We really showed him! Here, give me the head and I\'ll take care of it.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27097,'Я вижу всё, $N. Через Агату мне открывается всё сущее.' FROM `quest_template` b WHERE b.`id`=27097 AND BINARY b.`offerrewardtext`=BINARY 'I see everything, $N. Through Agatha all is known to me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27100,'<Вы просматриваете записи, пытаясь привести их в порядок.>' FROM `quest_template` b WHERE b.`id`=27100 AND BINARY b.`requestitemstext`=BINARY '<You scroll through the notes, trying to put them in order.>' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27112,'Поганища убиты?' FROM `quest_template` b WHERE b.`id`=27112 AND BINARY b.`requestitemstext`=BINARY 'Did you slay those abominations?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27148,'Без директора школа погрузится в хаос. Больше она не выпустит в мир своих мерзких «учеников». Спасибо.' FROM `quest_template` b WHERE b.`id`=27148 AND BINARY b.`offerrewardtext`=BINARY 'Without a headmaster, the school will descend into chaos. It will not put forth any more of its vile \'students\' into the field. Thank you.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27193,'Как твои дела?' FROM `quest_template` b WHERE b.`id`=27193 AND BINARY b.`requestitemstext`=BINARY 'What is your status?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27226,'Не дай моим морским волкам погибнуть!' FROM `quest_template` b WHERE b.`id`=27226 AND BINARY b.`requestitemstext`=BINARY 'Don\'t let my sea dogs die!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27271,'Добро пожаловать в Башню магов, $N. Я с интересом наблюдаю за твоими успехами.' FROM `quest_template` b WHERE b.`id`=27271 AND BINARY b.`offerrewardtext`=BINARY 'Welcome to the Wizard\'s Sanctum, $N. I have been watching your progress with interest.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27310,'Нужно уничтожить ещё больше их оружейных стоек, чтобы ослабить их боеспособность.' FROM `quest_template` b WHERE b.`id`=27310 AND BINARY b.`requestitemstext`=BINARY 'We\'ll need to destroy more of their weapon racks if we\'re going to put a dent in their ability to fight.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27314,'Иша Сумрачная Секира должна погибнуть, $N!' FROM `quest_template` b WHERE b.`id`=27314 AND BINARY b.`requestitemstext`=BINARY 'Isha Gloomaxe must meet her end, $N!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27316,'Значит, это правда! Но что оно здесь делает? А если оно здесь, значит, и грамота с барабанами где-то рядом!$B$BМожет, оно как-то связано с крылатым змеем, который только что появился? Кажется, я понимаю, что это за существо.' FROM `quest_template` b WHERE b.`id`=27316 AND BINARY b.`offerrewardtext`=BINARY 'It\'s true then! What is it doing here, though? And if it\'s here, that must mean that the writ and the drums are also nearby!$B$BMaybe there\'s some link between it and the wind serpent that just appeared? I think that I\'ve an idea what that creature is as well.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27320,'Почти уверен, это оно. Очень любопытно, $N. Что они здесь делают? Их используют как оружие?$B$BКрылатый змей улетел на северо-запад, к следующему утёсу. Может, там и барабаны?' FROM `quest_template` b WHERE b.`id`=27320 AND BINARY b.`offerrewardtext`=BINARY 'I\'m fairly certain that\'s it. This is very intriguing, $N. What are they doing here? Are they being used as a weapon?$B$BThe wind serpent flew northwest to that next bluff. Maybe that\'s where the drums are?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27320,'Нам нужна сама грамота, а не какой-нибудь тауренский подвесной свиток.' FROM `quest_template` b WHERE b.`id`=27320 AND BINARY b.`requestitemstext`=BINARY 'We\'ll need the actual writ, not just any tauren scroll hanging.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27325,'Это наверняка был голос Мудрой старицы!$B$BНужно быть очень осторожными, $N. Впереди большая опасность, если Магата Зловещий Тотем обратила на тебя внимание.' FROM `quest_template` b WHERE b.`id`=27325 AND BINARY b.`offerrewardtext`=BINARY 'Surely that was the voice of the Elder Crone!$B$BWe must be very careful, $N. Great danger lies ahead if Magatha Grimtotem has taken notice of you.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27329,'Лишь усмирив Арикару, ты узнаешь, где скрывается Магата Зловещий Тотем.' FROM `quest_template` b WHERE b.`id`=27329 AND BINARY b.`requestitemstext`=BINARY 'Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27354,'А, я ждал тебя, $N. Магинор Дюма отзывался о тебе с похвалой, а королевское поручение лишь подтверждает его слова. Для меня честь изготовить для тебя посох.' FROM `quest_template` b WHERE b.`id`=27354 AND BINARY b.`offerrewardtext`=BINARY 'Ah, I have been expecting you, $N. Maginor Dumas has spoken highly of you and the royal commission only confirms his words. It is an honor to be able to craft a staff for you.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27354,'Материалы для твоего оружия у тебя?' FROM `quest_template` b WHERE b.`id`=27354 AND BINARY b.`requestitemstext`=BINARY 'Did you bring the materials I\'ll need for your weapon?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27364,'Как обстановка?' FROM `quest_template` b WHERE b.`id`=27364 AND BINARY b.`requestitemstext`=BINARY 'Status?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27397,'Материалы для твоего оружия у тебя?' FROM `quest_template` b WHERE b.`id`=27397 AND BINARY b.`requestitemstext`=BINARY 'Did you bring the materials I\'ll need for your weapon?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27423,'Некогда упиваться боевой славой, $N. Нас ждёт работа. Не сомневаюсь, что новые звери уже на подходе.' FROM `quest_template` b WHERE b.`id`=27423 AND BINARY b.`offerrewardtext`=BINARY 'No time to bask in the battle glory, $N. We have a job to do. I have no doubt more of those beasts are on the way.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27451,'Как обстановка на Перекрестке Корина?' FROM `quest_template` b WHERE b.`id`=27451 AND BINARY b.`requestitemstext`=BINARY 'How are things looking in Corin\'s Crossing?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27452,'Всё идёт хорошо, $N?' FROM `quest_template` b WHERE b.`id`=27452 AND BINARY b.`requestitemstext`=BINARY 'Everything going alright so far, $N?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27489,'У нас нет времени, $N! Нужно двигаться дальше!' FROM `quest_template` b WHERE b.`id`=27489 AND BINARY b.`requestitemstext`=BINARY 'We have no time, $N!  We must press on!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27534,'Моя книга квитанций у тебя? Не терпится вернуться к делам!' FROM `quest_template` b WHERE b.`id`=27534 AND BINARY b.`requestitemstext`=BINARY 'Do you have my receipt book?  I can\'t wait to get back to business!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27551,'Что? Удалось что-то найти?' FROM `quest_template` b WHERE b.`id`=27551 AND BINARY b.`requestitemstext`=BINARY 'What?  Did you find something?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27596,'Ты принес сердце горы? Для меня его ценность поистине безгранична.' FROM `quest_template` b WHERE b.`id`=27596 AND BINARY b.`requestitemstext`=BINARY 'Do you have the Heart of the Mountain?  To me, its value is without limit.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27632,'Возможно, это та карта, которую вы ищете.' FROM `quest_template` b WHERE b.`id`=27632 AND BINARY b.`requestitemstext`=BINARY 'This might be the map you\'re after.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27679,'Агенты Реликвария уже направляются исследовать зал. Тебя ждут более важные дела.' FROM `quest_template` b WHERE b.`id`=27679 AND BINARY b.`offerrewardtext`=BINARY 'Reliquary agents are en route to investigate the chamber. You have more important matters to attend to.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27680,'Ты очень надёжный помощник, $N. Отправляйся к дискам и узнай всё, что сможешь. После этого немедленно доложи мне.' FROM `quest_template` b WHERE b.`id`=27680 AND BINARY b.`offerrewardtext`=BINARY 'You are a most reliable agent, $N. Proceed to the discs and learn all you can. Report back to me immediately after.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27693,'Нефритовая статуя вновь становится целой, и вы кладёте её в карман. Из центрального зала гробницы доносится звук движения.' FROM `quest_template` b WHERE b.`id`=27693 AND BINARY b.`offerrewardtext`=BINARY 'The jade statue becomes one again, and you place it in your pocket.  You hear a shifting noise in the tomb\'s central chamber.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27704,'Не отступай, $N. Твои действия позволят мне лично войти в храм.' FROM `quest_template` b WHERE b.`id`=27704 AND BINARY b.`requestitemstext`=BINARY 'You must not falter, $N. Your actions will pave the way for me to enter the temple myself.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27705,'Туда ему и дорога. Одним источником скверны в мире стало меньше.$B$BБлагодарю тебя за отвагу, $N.' FROM `quest_template` b WHERE b.`id`=27705 AND BINARY b.`offerrewardtext`=BINARY 'Good riddance. Another source of corruption in this world put to rest.$B$BI thank you for your bravery, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27709,'<Красная статуя опрокидывается, и вы убираете её обратно в сумки. Из центрального зала гробницы доносится грохот.>' FROM `quest_template` b WHERE b.`id`=27709 AND BINARY b.`offerrewardtext`=BINARY '<The red statue falls over, and you place it back in your bags.  You hear a rumbling noise in the tomb\'s central chamber.>' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27713,'Ты будешь слушать или нет?' FROM `quest_template` b WHERE b.`id`=27713 AND BINARY b.`requestitemstext`=BINARY 'Are you going to listen or not?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27729,'Теперь у тебя есть ещё одна история для внуков о том, что ты ради них совершаешь.' FROM `quest_template` b WHERE b.`id`=27729 AND BINARY b.`offerrewardtext`=BINARY 'You can add this to list of things you can tell your grandchildren that you\'ve done for them.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27739,'Тебе удалось победить Дробителя?' FROM `quest_template` b WHERE b.`id`=27739 AND BINARY b.`requestitemstext`=BINARY 'Have you defeated Hogger?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27765,'Спасибо, что удалось так быстро всё собрать, $N.' FROM `quest_template` b WHERE b.`id`=27765 AND BINARY b.`offerrewardtext`=BINARY 'Thank you for gathering these so quickly, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27765,'Яйца у тебя?' FROM `quest_template` b WHERE b.`id`=27765 AND BINARY b.`requestitemstext`=BINARY 'Have you brought the eggs?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27766,'Это ужасное задание было необходимо, $N.$b$bСкоро тебе всё откроется. А пока знай:$b$bЯ не простой гоблин.$b$bЯ служу госпоже невообразимого могущества, и её намерения здесь не так мрачны, как может показаться.' FROM `quest_template` b WHERE b.`id`=27766 AND BINARY b.`offerrewardtext`=BINARY 'This grisly task was necessary, $N.$b$bAll will be revealed to you soon.  For now, know this:$b$bI am no ordinary goblin.$b$bI serve a mistress of unimaginable power, and her motives here are not as dark as they might seem.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27766,'Моя просьба выполнена?' FROM `quest_template` b WHERE b.`id`=27766 AND BINARY b.`requestitemstext`=BINARY 'Have you done as I asked?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27770,'Мы найдём в этих драконах хоть крупицу добра, $N. В диких яйцах, которые ты находишь, в телах убитых дракончиков или в яйцах, которые Никсондра откладывает благодаря нам... мы найдём неосквернённого чёрного дракона.' FROM `quest_template` b WHERE b.`id`=27770 AND BINARY b.`offerrewardtext`=BINARY 'We will find a shred of good within these dragons, $N.  Whether it is in the wild eggs you found, the bodies of the whelplings you slew, or the eggs that we have encouraged Nyxondra to lay... we will find an untainted black dragon.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27771,'Помни, $N... это ради блага чёрной стаи. Мы здесь, чтобы спасти их, а не причинить им вред. Это лишь один шаг к их исцелению.' FROM `quest_template` b WHERE b.`id`=27771 AND BINARY b.`requestitemstext`=BINARY 'Remember, $N... this is for the good of the black dragonflight.  We are here to redeem them, not to hurt them.  This is but a step in their recovery.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27776,'Сами виноваты, нечего стоять так близко к краю' FROM `quest_template` b WHERE b.`id`=27776 AND BINARY b.`requestitemstext`=BINARY 'It\'s their own fault for standing so close to the edge' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27789,'Ещё не совсем готово. Нужно ещё немного времени.' FROM `quest_template` b WHERE b.`id`=27789 AND BINARY b.`requestitemstext`=BINARY 'Not quite done yet.  Need some more time.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27792,'У тебя тяжёлые сумки. Полагаю, от освобождённых артефактов?' FROM `quest_template` b WHERE b.`id`=27792 AND BINARY b.`requestitemstext`=BINARY 'Your bags look heavy.  Heavy with liberated artifacts, I presume?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27826,'Ценный у тебя груз, $N.' FROM `quest_template` b WHERE b.`id`=27826 AND BINARY b.`requestitemstext`=BINARY 'That\'s some precious cargo you carry there, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27904,'Остаётся надеяться, что это поможет найти лекарство, $N. Спасибо за доставку.' FROM `quest_template` b WHERE b.`id`=27904 AND BINARY b.`offerrewardtext`=BINARY 'I can only hope this will lead to a cure, $N. Thank you for bringing it to me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27904,'Кристаллы у тебя?' FROM `quest_template` b WHERE b.`id`=27904 AND BINARY b.`requestitemstext`=BINARY 'Do you have the crystals?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27914,'Ты очень помогаешь мне и моим сородичам, $N. Прими это в знак моей благодарности и твоей отваги.' FROM `quest_template` b WHERE b.`id`=27914 AND BINARY b.`offerrewardtext`=BINARY 'You have performed a great service for me and my kind, $N. Accept this as a symbol of my gratitude, and of your courage.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 27915,'Приятно снова видеть тебя, $N. Как благородно с твоей стороны и дальше мне помогать.' FROM `quest_template` b WHERE b.`id`=27915 AND BINARY b.`offerrewardtext`=BINARY 'I am pleased to see you once again, $N. You are truly noble to assist me further.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 27985,'<Вы просматриваете молитву ночного эльфа.>' FROM `quest_template` b WHERE b.`id`=27985 AND BINARY b.`requestitemstext`=BINARY '<You glance over the night elf\'s prayer.>' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28041,'<Вы забираете свежую тушу.>' FROM `quest_template` b WHERE b.`id`=28041 AND BINARY b.`requestitemstext`=BINARY '<You gather up the fresh carcass.>' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28044,'Ты меня слышишь, $n? Коготь у тебя?' FROM `quest_template` b WHERE b.`id`=28044 AND BINARY b.`requestitemstext`=BINARY 'Can you hear me in there, $n? Do you have the claw?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28062,'Эрцгерцог Кальциндер изгнан из Азерота. От него осталось лишь небольшое пятно пепла там, где он стоял.$b$bТвоя работа здесь закончена.' FROM `quest_template` b WHERE b.`id`=28062 AND BINARY b.`offerrewardtext`=BINARY 'Archduke Calcinder has been banished from Azeroth.  All that remains is a small, ashy spot where he once stood.$b$bYour work here is done.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28093,'Добро пожаловать, $r.' FROM `quest_template` b WHERE b.`id`=28093 AND BINARY b.`requestitemstext`=BINARY 'Welcome, $r.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28098,'$N, тебе нужно разобраться с Сумеречным повелителем небес Рихтофеном!' FROM `quest_template` b WHERE b.`id`=28098 AND BINARY b.`requestitemstext`=BINARY '$N, you must take care of Twilight Skymaster Richtofen!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28125,'Сколько этих доспехов удалось собрать?$B$BДля следующего дела тебе понадобится надёжная маскировка.' FROM `quest_template` b WHERE b.`id`=28125 AND BINARY b.`requestitemstext`=BINARY 'How much of that armor have you collected?$B$BYou\'re going to want to be well disguised for the next thing that you\'re going to have to do.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28127,'Ты отдаёшь так много, ничего не требуя взамен.$B$BЖители Тысячи Игл благодарны тебе, как и я.' FROM `quest_template` b WHERE b.`id`=28127 AND BINARY b.`offerrewardtext`=BINARY 'You give so much of yourself without requiring anything in return.$B$BThe people of Thousand Needles are grateful, as am I.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28131,'Ещё одна демоническая угроза устранена. Пора найти их повелителя.' FROM `quest_template` b WHERE b.`id`=28131 AND BINARY b.`offerrewardtext`=BINARY 'Another demonic menace gone. It is time to find their master.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28144,'Верни наши «припасы», $N!' FROM `quest_template` b WHERE b.`id`=28144 AND BINARY b.`requestitemstext`=BINARY 'Recover our "supplies," $N!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28146,'На несколько дней оно будет сыто и довольно. Доброе дело, $N!' FROM `quest_template` b WHERE b.`id`=28146 AND BINARY b.`offerrewardtext`=BINARY 'This should keep it happy and content for a few days. You\'ve done a good thing here, $N!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28196,'<Надзиратель Штиллец перелистывает дневник, бормоча под нос.>$B$BБред сумасшедшего! Ясно, что он ел эти грибы. Хорошо, что дневник попал ко мне, $N. Я сам его сожгу!' FROM `quest_template` b WHERE b.`id`=28196 AND BINARY b.`offerrewardtext`=BINARY '<Warden Stillwater flips through the journal, reading under his breath.>$B$BRamblings of a mad man! Clearly he had been ingesting the mushrooms. It is good that you brought this to me, $N. I will burn it myself!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28196,'Что это?' FROM `quest_template` b WHERE b.`id`=28196 AND BINARY b.`requestitemstext`=BINARY 'What\'s this?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28209,'Достань ключ!' FROM `quest_template` b WHERE b.`id`=28209 AND BINARY b.`requestitemstext`=BINARY 'Get the key!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28210,'Каков счёт?' FROM `quest_template` b WHERE b.`id`=28210 AND BINARY b.`requestitemstext`=BINARY 'What\'s the tally?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28228,'Когда-нибудь мои ветви раскинутся над обновлённым лесом, полным жизни и надежды.$B$BПрощай, $n. Наберись терпения... и если проживёшь достаточно долго, то однажды, быть может, увидишь меня вновь.' FROM `quest_template` b WHERE b.`id`=28228 AND BINARY b.`offerrewardtext`=BINARY 'Someday I will spread my branches across a renewed forest, full of life and hope.$B$BFarewell, $n. Have patience... and if you live long, you may see me again one day.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28229,'Вода из лунного колодца быстро впитывается в землю, мягко светясь. Через несколько мгновений раздаётся шорох, и перед вашими глазами появляется маленький росток.' FROM `quest_template` b WHERE b.`id`=28229 AND BINARY b.`offerrewardtext`=BINARY 'The moonwell water quickly seeps into the ground with a soft glow. A few moments later, a rustling noise is heard, and a small sprout pops up before your eyes.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28261,'Хватит! Твоё рвение впечатляет, но оно неразумно. Если слишком долго смотреть сквозь завесу без подготовки, твой разум не выдержит.$B$BОстальное — моё, $n. А пока я призываю тебя обратно.' FROM `quest_template` b WHERE b.`id`=28261 AND BINARY b.`offerrewardtext`=BINARY 'Enough! Your enthusiasm is impressive, but foolish. Gazing through the veil for too long without practice will break your mind.$B$BThe rest will be mine, $n. For now, I summon you back to me.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28263,'Приятно снова тебя видеть, $N. Штормград нуждается в твоих умениях.' FROM `quest_template` b WHERE b.`id`=28263 AND BINARY b.`offerrewardtext`=BINARY 'It\'s good to see you again, $N. Stormwind has need of your skills.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28266,'В чём дело, страшно?' FROM `quest_template` b WHERE b.`id`=28266 AND BINARY b.`requestitemstext`=BINARY 'What\'s the matter, are you scared?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28313,'Есть успехи?' FROM `quest_template` b WHERE b.`id`=28313 AND BINARY b.`requestitemstext`=BINARY 'Any luck out there?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28315,'Давай, $N, там ещё остались враги. Наша работа не закончена.' FROM `quest_template` b WHERE b.`id`=28315 AND BINARY b.`requestitemstext`=BINARY 'Come on, $N, there\'s still more of them left.  Our job isn\'t done.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28316,'Вот и ты, $N.' FROM `quest_template` b WHERE b.`id`=28316 AND BINARY b.`requestitemstext`=BINARY 'You\'ve arrived, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28325,'Отличная работа, $N. Эта зараза тебе удивительно нипочём. Как-нибудь придётся тебя обследовать.' FROM `quest_template` b WHERE b.`id`=28325 AND BINARY b.`offerrewardtext`=BINARY 'Excellent work, $N. You are incredibly resilient to this blight. We\'ll have to take you in for testing some time.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28325,'Принеси мне те канистры!' FROM `quest_template` b WHERE b.`id`=28325 AND BINARY b.`requestitemstext`=BINARY 'Bring me those canisters!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28330,'Да?' FROM `quest_template` b WHERE b.`id`=28330 AND BINARY b.`requestitemstext`=BINARY 'Yes?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28376,'Тебе удалось одолеть того дракона!?$b$bПоразительно!' FROM `quest_template` b WHERE b.`id`=28376 AND BINARY b.`requestitemstext`=BINARY 'You took down that dragon!?$b$bRemarkable!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28382,'Пусть их кровь оросит наше древо. Ты хорошо сражаешься, $n.' FROM `quest_template` b WHERE b.`id`=28382 AND BINARY b.`offerrewardtext`=BINARY 'May their blood water our tree. You fight well, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28398,'<Наставник, обучающий тех, чей путь — $C, быстро листает гримуар.>$B$BЯ уже увидел дюжину заклинаний, о существовании которых даже не подозревал. Это очень пригодится, $N.' FROM `quest_template` b WHERE b.`id`=28398 AND BINARY b.`offerrewardtext`=BINARY '<The $C trainer pages through the grimoire quickly.>$B$BI\'ve already seen a dozen spells I never knew existed. This will be most helpful, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28398,'Гримуар пироманта удалось захватить?' FROM `quest_template` b WHERE b.`id`=28398 AND BINARY b.`requestitemstext`=BINARY 'Have you managed to capture the pyromancer\'s grimoire?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28419,'Уже здесь?' FROM `quest_template` b WHERE b.`id`=28419 AND BINARY b.`requestitemstext`=BINARY 'Back already?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28420,'Посмотрим на эти шкуры.' FROM `quest_template` b WHERE b.`id`=28420 AND BINARY b.`requestitemstext`=BINARY 'Let\'s take a look at those hides.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28421,'Остерегайся этих обсидиановых элементалей. У них привычка подкрадываться незаметно.' FROM `quest_template` b WHERE b.`id`=28421 AND BINARY b.`requestitemstext`=BINARY 'You\'ll want to watch out for those obsidian elementals.  They have a tendency to sneak up on you.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28486,'Приветствую, $N!' FROM `quest_template` b WHERE b.`id`=28486 AND BINARY b.`requestitemstext`=BINARY 'Hail, $N!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28507,'Нужно убедить гоблинов Прибамбасска встать на нашу сторону, $C.' FROM `quest_template` b WHERE b.`id`=28507 AND BINARY b.`offerrewardtext`=BINARY 'We have to persuade the goblins of Gadgetzan to side with us, $C.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28550,'Каждый день мы отражаем мощные контратаки Орды, $C. Чтобы сдержать их, нам нужна каждая пара рук.' FROM `quest_template` b WHERE b.`id`=28550 AND BINARY b.`offerrewardtext`=BINARY 'We face heavy Horde counterattacks daily, $C. We need every pair of hands we can get to keep them at bay.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28551,'Орда оказывает нам ожесточённое сопротивление, $c. Мы рады любым подкреплениям.' FROM `quest_template` b WHERE b.`id`=28551 AND BINARY b.`offerrewardtext`=BINARY 'We\'re facing heavy resistance from the Horde, $c. Any reinforcements are welcome.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28653,'Приветствую, $N.$b$bВижу, оружие у тебя есть. А драться умеешь?' FROM `quest_template` b WHERE b.`id`=28653 AND BINARY b.`offerrewardtext`=BINARY 'Greetings, $N.$b$bI see you wield a weapon.  Can you fight?' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28726,'Мрачная работа. Мне больно причинять такое зло лесным существам, даже если они осквернены.' FROM `quest_template` b WHERE b.`id`=28726 AND BINARY b.`requestitemstext`=BINARY 'This is grim work. It pains me to have to inflict such violence on creature of the forest, corrupt or not.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28727,'Я люблю эти леса. Хочу, чтобы скверна исчезла из них без следа. Когда я вернусь сюда в следующий раз, пусть сердце будет легче.' FROM `quest_template` b WHERE b.`id`=28727 AND BINARY b.`requestitemstext`=BINARY 'I adore these forests. I want to see the corruption purged from them completely. When next I return, I want to do so with a lighter heart.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28745,'Теперь нам сов на месяц торговли хватит, дружище. Ничего не скажешь, молодец.' FROM `quest_template` b WHERE b.`id`=28745 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve put us in enough owls for us to sell for a month, friend. Gotta hand it to ya.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28757,'Благодаря тебе у нас есть немного времени, $N, но теперь нам предстоит решить ещё более серьёзные проблемы.' FROM `quest_template` b WHERE b.`id`=28757 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve bought us a little time, $N, but we\'ve got even bigger problems to deal with now.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28759,'Отличная работа, $N. От тебя немалая польза нашему гарнизону. Пора приступать к тренировкам!' FROM `quest_template` b WHERE b.`id`=28759 AND BINARY b.`offerrewardtext`=BINARY 'Excellent work, $N. You\'ve turned out to be quite an asset to this garrison. It\'s time for you to train!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28759,'Убей шпионов!' FROM `quest_template` b WHERE b.`id`=28759 AND BINARY b.`requestitemstext`=BINARY 'Kill the spies!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28762,'Благодаря тебе у нас есть немного времени, $N, но теперь нам предстоит решить ещё более серьёзные проблемы.' FROM `quest_template` b WHERE b.`id`=28762 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve bought us a little time, $N, but we\'ve got even bigger problems to deal with now.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
