INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28788,'Это правда, мы попали в засаду. Я не смею посылать туда новых солдат и рисковать ещё и их жизнями. Мне нужен доброволец. Тот, кто готов рискнуть жизнью!' FROM `quest_template` b WHERE b.`id`=28788 AND BINARY b.`offerrewardtext`=BINARY 'It\'s true, we were ambushed. I don\'t dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28799,'На первый взгляд этот столб ничем не примечателен, но ваши познания в археологии подсказывают иное. Дворфийский рунический камень помог бы пролить свет на его происхождение.' FROM `quest_template` b WHERE b.`id`=28799 AND BINARY b.`requestitemstext`=BINARY 'At first glance, this pillar seems very plain, but your knowledge of archaeology tells you differently.  If you had a Dwarf Rune Stone, its originations could be brought to light.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28802,'Этот каменный обелиск явно представляет собой некий план или карту, но прочесть его целиком не удаётся. Возможно, Тол\'вирские древние письмена помогли бы разобраться в знаках.' FROM `quest_template` b WHERE b.`id`=28802 AND BINARY b.`requestitemstext`=BINARY 'This stone obelisk is obviously some sort of layout or map, but it isn\'t completely readable.  Perhaps if you had a Tol\'vir Hieroglyphic keystone, the markings might make more sense.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28804,'Это определённо какой-то план, но чего именно — вы не уверены. Его отличительные знаки можно было бы сравнить с Дворфийским руническим камнем.' FROM `quest_template` b WHERE b.`id`=28804 AND BINARY b.`requestitemstext`=BINARY 'These are definitely some sort of plans, but for what you aren\'t certain.  They bear distinctive markings that could be compared to a Dwarf Rune Stone.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28805,'Да, $c?' FROM `quest_template` b WHERE b.`id`=28805 AND BINARY b.`requestitemstext`=BINARY 'Yes, $c?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 28815,'<Вы открываете документы в поисках примечательных сведений.>' FROM `quest_template` b WHERE b.`id`=28815 AND BINARY b.`offerrewardtext`=BINARY '<You open the documents and look for any noteworthy information.>' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28815,'Похоже, это нужные документы.' FROM `quest_template` b WHERE b.`id`=28815 AND BINARY b.`requestitemstext`=BINARY 'These appear to be the right documents.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 28824,'Дело сделано, $r?' FROM `quest_template` b WHERE b.`id`=28824 AND BINARY b.`requestitemstext`=BINARY 'Is it done, $r?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
