INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29092,'Поистине мрачные вести. Мы должны сделать всё возможное, чтобы не допустить этой войны.' FROM `quest_template` b WHERE b.`id`=29092 AND BINARY b.`offerrewardtext`=BINARY 'This is grave news indeed. We must do everything in our power to stop this war from coming to pass.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29100,'Задача будет непростая, $n.' FROM `quest_template` b WHERE b.`id`=29100 AND BINARY b.`requestitemstext`=BINARY 'Dis won\'t be no easy task, $n.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29125,'Да?' FROM `quest_template` b WHERE b.`id`=29125 AND BINARY b.`requestitemstext`=BINARY 'Yes?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29138,'К нашему счастью, силы Рагнароса куда чаще ранят наших воинов, чем убивают наповал. Их атаки сами прижигают нанесённые раны. Это очень больно, но лучше смерти.' FROM `quest_template` b WHERE b.`id`=29138 AND BINARY b.`requestitemstext`=BINARY 'To our fortune, Ragnaros\' forces far more often injure our warriors than outright kill them. Their attacks naturally cauterize the wounds they inflict. It\'s very painful, but it\'s better than death.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29139,'Удалось найти места для посадки? Понимаю, почва там бедная.' FROM `quest_template` b WHERE b.`id`=29139 AND BINARY b.`requestitemstext`=BINARY 'Did you find some places to plant them? I realize it\'s a bit barren out there.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29147,'<Сквозь щебетание, уханье и неистовое карканье своих пернатых товарищей вы слышите, как Мата Коготь говорит с вами издалека.>$b$bОтличная работа, $r. Теперь, когда стая собралась, мы нанесём удар.' FROM `quest_template` b WHERE b.`id`=29147 AND BINARY b.`offerrewardtext`=BINARY '<Amidst the chirps, hoots, and frenzied caws of your fellow birds, you hear the voice of Matoclaw speaking to you from afar.>$b$bWell done, $r. Now that the flock is assembled, we strike.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29147,'Да?' FROM `quest_template` b WHERE b.`id`=29147 AND BINARY b.`requestitemstext`=BINARY 'Yes?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29179,'Нельзя позволить этим элементалям занять хоть клочок земли. Вряд ли они прекратят нападения настолько надолго, чтобы мы успели его вернуть.' FROM `quest_template` b WHERE b.`id`=29179 AND BINARY b.`requestitemstext`=BINARY 'We cannot allow these elementals to take any ground. They\'re not likely to lapse in their attacks long enough for us to take it back.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29181,'Приятно снова тебя видеть.' FROM `quest_template` b WHERE b.`id`=29181 AND BINARY b.`requestitemstext`=BINARY 'It is good to see you again. ' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29219,'Задача будет непростая, $n.' FROM `quest_template` b WHERE b.`id`=29219 AND BINARY b.`requestitemstext`=BINARY 'Dis won\'t be no easy task, $n.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29220,'Видать, духи на твоей стороне, $c.' FROM `quest_template` b WHERE b.`id`=29220 AND BINARY b.`offerrewardtext`=BINARY 'It seems da spirits be wit\' you, $c.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29221,'Спасибо за помощь, $n. Этим змеям, кажется, конца нет.' FROM `quest_template` b WHERE b.`id`=29221 AND BINARY b.`offerrewardtext`=BINARY 'Thanks for da help, $n.  Dese serpents, dere don\'t seem to be an end to dem.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29223,'О змеях мы всё знаем, $n. Но там скрывается ещё что-то... Джунгли ожили, $c!' FROM `quest_template` b WHERE b.`id`=29223 AND BINARY b.`offerrewardtext`=BINARY 'We know all about the serpents, $n.  But there is something else out there lurking...  The jungle has come to life, $c!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29233,'Сначала были змеи, потом пантеры, а теперь — кровожадные тролли.$b$bХорошо, что ты здесь, $c. Троллей, которых нужно убить, предостаточно.' FROM `quest_template` b WHERE b.`id`=29233 AND BINARY b.`offerrewardtext`=BINARY 'First we had snakes, then we had panthers, now we have blood-thirsty trolls.$b$bIt\'s good that you\'re here, $c, there are plenty of trolls to kill.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29236,'Дела плохи, $n.' FROM `quest_template` b WHERE b.`id`=29236 AND BINARY b.`offerrewardtext`=BINARY 'Dis don\'t look very good, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29249,'Из земли показывается красный цветок.' FROM `quest_template` b WHERE b.`id`=29249 AND BINARY b.`offerrewardtext`=BINARY 'A red flower pops its head out of the soil.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29252,'Удалось что-нибудь найти, $n?' FROM `quest_template` b WHERE b.`id`=29252 AND BINARY b.`requestitemstext`=BINARY 'Did you find something, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29281,'Да, $n?' FROM `quest_template` b WHERE b.`id`=29281 AND BINARY b.`requestitemstext`=BINARY 'Yes, $n?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29330,'Вопреки всему Тралл спасён. Аггра была права, не теряя надежды на спасение мирового шамана.' FROM `quest_template` b WHERE b.`id`=29330 AND BINARY b.`offerrewardtext`=BINARY 'Despite all odds, Thrall has been saved. Aggra was right to hold out hope for the world-shaman.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29338,'Будь наготове, $N.' FROM `quest_template` b WHERE b.`id`=29338 AND BINARY b.`offerrewardtext`=BINARY 'Be ready, $N.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29436,'Мягкой посадки!' FROM `quest_template` b WHERE b.`id`=29436 AND BINARY b.`requestitemstext`=BINARY 'Happy landings!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29520,'Удалось найти место для твоего нового знамени?' FROM `quest_template` b WHERE b.`id`=29520 AND BINARY b.`requestitemstext`=BINARY 'Were you able to find a place for that new banner of yours?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29583,'Я очень надеялся, что на мой зов откликнется именно тот гном, которого я искал.$B$B<Механолог Морфалиус осматривает вас.>$B$BЧто ж, полагаю, ты сойдёшь.' FROM `quest_template` b WHERE b.`id`=29583 AND BINARY b.`offerrewardtext`=BINARY 'I was truly hoping that the gnome I sought out would be the one to answer my call.$B$B<Artificer Morphalius looks you over.>$B$BI suppose you\'ll do.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29659,'Полагаю, нужная вещь у тебя?' FROM `quest_template` b WHERE b.`id`=29659 AND BINARY b.`requestitemstext`=BINARY 'You\'ve obtained it, I assume?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29664,'Тебе ещё рано со мной сражаться. Сначала зажги жаровни.' FROM `quest_template` b WHERE b.`id`=29664 AND BINARY b.`requestitemstext`=BINARY 'You are not yet ready to face me. First, you must light the braziers.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29769,'Нужно перебить их всех до последнего! Ну, одного, пожалуй, можно оставить в живых, но если их будет больше, все наши беды начнутся заново!' FROM `quest_template` b WHERE b.`id`=29769 AND BINARY b.`requestitemstext`=BINARY 'We need to kill them down to the very last one! We can leave that one alive I suppose, but if there\'s more than one, our troubles are going to start all over again!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29778,'Старейшина Шаопай уже давно записывает великую мудрость нашего народа и развешивает свитки, чтобы каждый мог её прочесть. Меня поражает его стойкость перед лицом святотатства, которое творят эти хозены. Годы труда уничтожены, а он сохраняет спокойствие.$B$BПризнаюсь, у меня такого качества нет.' FROM `quest_template` b WHERE b.`id`=29778 AND BINARY b.`requestitemstext`=BINARY 'Elder Shaopai has long been responsible for documenting the great wisdoms of our people and hanging them for all to see. What amazes me is his fortitude in the light of the great sacrilege these hozen are commiting. Many years of work destroyed, and yet he remains calm. $B$BI must admit, that is a quality that I do not possess.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29779,'Доброта закончилась. Пора убивать обезьян.' FROM `quest_template` b WHERE b.`id`=29779 AND BINARY b.`requestitemstext`=BINARY 'The time for kindness is done. We have monkeys to kill.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 29803,'Приятно снова видеть тебя, $N.' FROM `quest_template` b WHERE b.`id`=29803 AND BINARY b.`requestitemstext`=BINARY 'It is good to see you again, $N.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 29851,'Для меня честь стоять рядом со столь яростным воином.$B$BТвои деяния принесли честь тебе и твоему народу, $N!' FROM `quest_template` b WHERE b.`id`=29851 AND BINARY b.`offerrewardtext`=BINARY 'I am honored to stand in the presence of such a fierce warrior.$B$BYou have brought honor to yourself and to your people, $N!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31137,'Приятно познакомиться, $n. Ты наверняка слышишь разговоры об операции «Гномреган». Позволь рассказать, что произошло и почему мы покинули дворфийский город Стальгорн.' FROM `quest_template` b WHERE b.`id`=31137 AND BINARY b.`offerrewardtext`=BINARY 'It\'s good to meet you, $n. You\'ve probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31139,'Благодаря тебе у нас есть немного времени, $N, но теперь нам предстоит решить ещё более серьёзные проблемы.' FROM `quest_template` b WHERE b.`id`=31139 AND BINARY b.`offerrewardtext`=BINARY 'You\'ve bought us a little time, $N, but we\'ve got even bigger problems to deal with now.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31140,'Отличная работа, $N. От тебя немалая польза нашему гарнизону. Пора приступать к тренировкам!' FROM `quest_template` b WHERE b.`id`=31140 AND BINARY b.`offerrewardtext`=BINARY 'Excellent work, $N. You\'ve turned out to be quite an asset to this garrison. It\'s time for you to train!' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31140,'Убей шпионов!' FROM `quest_template` b WHERE b.`id`=31140 AND BINARY b.`requestitemstext`=BINARY 'Kill the spies!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31156,'Учась друг у друга, мы прославим наши народы. Из тебя выйдет великий $c. По крайней мере, я приложу к этому все силы. А сам я узнаю обычаи твоего народа.' FROM `quest_template` b WHERE b.`id`=31156 AND BINARY b.`offerrewardtext`=BINARY 'We will honor our respective peoples by learning from each other. You will become a great $c. If I have anything to say about it. And I will learn the ways of your people.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31156,'А-а, вот и ты.' FROM `quest_template` b WHERE b.`id`=31156 AND BINARY b.`requestitemstext`=BINARY 'Ahh, you have come.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31157,'Хорошо, хорошо. Первое испытание позади. Я вижу, мы многому научимся друг у друга.' FROM `quest_template` b WHERE b.`id`=31157 AND BINARY b.`offerrewardtext`=BINARY 'Good, good. Your first challenge surpassed. We will learn much from each other. I can see.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31158,'Сила — не главное в победе над врагом и уж точно не главное, если хочешь выжить. В бою важен баланс. Всему своё время и место.' FROM `quest_template` b WHERE b.`id`=31158 AND BINARY b.`requestitemstext`=BINARY 'Strength isn\'t da end all of defeating ya enemy, and it most certainly isn\'t tha end all of stayin\' alive. Fightin\' is about balance. Everytin has its time and place.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31160,'Вряд ли с ними будет трудно, дружище, но если не будешь проворно двигаться, они тебе все лодыжки исцарапают.' FROM `quest_template` b WHERE b.`id`=31160 AND BINARY b.`requestitemstext`=BINARY 'I doubt dey too much of a challenge, mon, but they\'ll still claw up ya ankles if ya don\'t stay quick footed.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31161,'А ты неплохо справляешься. Когда-нибудь тебе не будет равных.' FROM `quest_template` b WHERE b.`id`=31161 AND BINARY b.`offerrewardtext`=BINARY 'Ya handle yerself quite well. Ya gonna be quite powerful some day.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31165,'Ах, приятно познакомиться.' FROM `quest_template` b WHERE b.`id`=31165 AND BINARY b.`requestitemstext`=BINARY 'Ah, I am pleased to meet you.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31166,'Отличная работа, $n.' FROM `quest_template` b WHERE b.`id`=31166 AND BINARY b.`offerrewardtext`=BINARY 'You have done well, $n.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31170,'А, добро пожаловать. Я обучаю твой народ искусству, которым владеет $c, и, похоже, оно им вполне подходит. Возможно, и тебе оно дастся так же легко.' FROM `quest_template` b WHERE b.`id`=31170 AND BINARY b.`offerrewardtext`=BINARY 'Ah, welcome. I have been teaching your people the ways of the $c, and they seem to be well suited for it. Perhaps you too will take to it as quickly as they.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 31171,'Думаю, основные приёмы техники «Лапа тигра» тебе уже покорились, $n. Возможно, тебе всё же удастся меня впечатлить.' FROM `quest_template` b WHERE b.`id`=31171 AND BINARY b.`offerrewardtext`=BINARY 'I think, you\'ve mastered the basics of the Tiger Palm technique, $n. Perhaps you will impress me, after all.' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31729,'Где тебе удалось собрать такую любопытную команду?' FROM `quest_template` b WHERE b.`id`=31729 AND BINARY b.`requestitemstext`=BINARY 'Where did you acquire such an intriguing team?' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31732,'Чего ты ждёшь?! Выжги землю у них под ногами!' FROM `quest_template` b WHERE b.`id`=31732 AND BINARY b.`requestitemstext`=BINARY 'What are you waiting for?! Scorch the ground beneath them!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 31735,'Мы выполним свою задачу, но сейчас важнее всего тот чернокнижник!' FROM `quest_template` b WHERE b.`id`=31735 AND BINARY b.`requestitemstext`=BINARY 'We will complete our mission, but right now our priority is that warlock!' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 32016,'Пусть звёзды благоволят тебе, $n.' FROM `quest_template` b WHERE b.`id`=32016 AND BINARY b.`offerrewardtext`=BINARY 'May the stars smile upon you, $n. ' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 32016,'Пусть эти обереги принесут тебе удачу, $n.' FROM `quest_template` b WHERE b.`id`=32016 AND BINARY b.`requestitemstext`=BINARY 'May these charms bring you great luck, $n.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) SELECT 32017,'Пусть звёзды благоволят тебе, $n.' FROM `quest_template` b WHERE b.`id`=32017 AND BINARY b.`offerrewardtext`=BINARY 'May the stars smile upon you, $n. ' ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='',VALUES(`offerrewardtext_loc8`),`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) SELECT 32017,'Пусть эти обереги принесут тебе удачу, $n.' FROM `quest_template` b WHERE b.`id`=32017 AND BINARY b.`requestitemstext`=BINARY 'May these charms bring you great luck, $n.' ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='',VALUES(`requestitemstext_loc8`),`requestitemstext_loc8`);
